INSERT INTO `kaizen` (`id_kaizen`, `categoria_kaizen`, `tipo_kaizen`, `tempo_kaizen`, `custo_kaizen`, `reducao_kaizen`, `destaque_kaizen`, `onde_kaizen`, `resultado_kaizen`, `imagem1_kaizen`, `imagem2_kaizen`, `colaborador_kaizen`, `colaborador1_kaizen`, `colaborador2_kaizen`, `colaborador3_kaizen`, `colaborador4_kaizen`, `lider_kaizen`, `datacadastro_kaizen`, `dataconclusao_kaizen`, `status_kaizen`, `admin_kaizen`, `pontos_kaizen`, `unidade_kaizen`, `setor_kaizen`, `outrosdep_kaizen`, `qual_kaizen`, `incidente_kaizen`, `obs_kaizen`) VALUES
(1, 0, 4, 0, 0, 0, 0, '', 'Confeccionar adaptador para colocar no port lança prequench ao inserir termopar para curva de aquecimento Reator 03', '', '', 1080, 1081, 0, 0, 0, 0, '2020-07-15', '2022-07-26', 2, 1, 2, 1, 0, 0, '', 0, ''),
(2, 0, 4, 0, 0, 0, 0, '', 'Antes tinha 2 PC’s na mesa de trabalho do almoxarifado, para utilizar a impressora de etiquetas. \nConversei com o Fernando setor TI para verificar se tinha como configurar a impressora Zebra de etiquetas no PC de trabalho para melhorar ergonomicamente a mesa de trabalho do almoxarifado, o Fernando baixou o programa da impressora no PC e configurou o mesmo então foi eliminado o outro CP melhorando e agilizando o trabalho para a impressão de etiquetas e melhorou ergonomicamente a estação de trabalho.', '', '', 1070, 0, 0, 0, 0, 0, '2020-07-28', '2020-07-28', 2, 0, 0, 1, 0, 0, '', 1, ''),
(3, 0, 2, 50, 0, 0, 0, '', 'Foi Criado uma ART (analise de Risco de Trabalho) da liberação do peletizador para manutenção, facilitando assim os trabalhos da manutenção na descontaminação  do mesma para reparos do equipamento.  ', '', '', 1081, 1087, 1079, 0, 0, 0, '2020-07-29', '2020-07-29', 2, 0, 0, 1, 0, 0, '', 0, ''),
(4, 0, 3, 12, 0, 0, 0, '', 'Foi instalada uma bomba para puxar agua da superfície da lagoa, o objetivo é diminuir o impacto da agua suja na qualidade do processo,  e no bom funcionamento dos equipamentos que utilizam agua da quench, evitando o entupimentos dos filtros de quench e possivelmente a queda das linhas produtivas por falta de agua de resfriamento. ', '', '', 1081, 1066, 0, 0, 0, 0, '2020-07-29', '2020-07-29', 2, 0, 0, 1, 0, 0, '', 1, ''),
(5, 0, 2, 0, 10000, 0, 0, '', 'Estufa de secagem e esterilização, faz uso do calor para a realização de secagem de produto controlado pelo termostato, porem para confirmação da temperatura era usado um medidor de temperatura portátil, foi instalado um controlador temperatura da NUVUS modelo:LDS496130000 que já tem a indicação de temperatura com precisão integrado, não necessita mais de uso do medidor de temperatura portátil tem regulagem mais precisa da temperatura e tem alarme de temperatura  mínimo, máximo.', '', '', 1071, 1157, 0, 0, 0, 0, '2020-08-04', '2020-08-04', 2, 0, 0, 1, 0, 0, '', 1, ''),
(6, 0, 4, 24, 0, 0, 0, '', 'Instalar suporte com álcool gel próximo ao relógio de ponto.', '', '', 1080, 0, 0, 0, 0, 0, '2020-08-05', '2020-08-05', 2, 0, 0, 1, 0, 0, '', 0, ''),
(7, 0, 4, 0, 0, 0, 0, '', 'Foi encapado teclado da Sala de Controle para facilitar na limpeza.', '', '', 1080, 1081, 0, 0, 0, 0, '2020-08-05', '2020-08-05', 2, 0, 0, 1, 0, 0, '', 1, ''),
(8, 0, 2, 0, 0, 0, 0, '', 'Para facilitar e economizar tempo e trabalho, foram criadas algumas macros em uma planilha de Excel on de o lab realiza a média das corridas, quando é preciso fazer o fechamento da corrida. Os dados da corrida são inseridos na planilha e a macro realiza a formatação dos dados, tornando o processo mais rápido.', '', '', 1090, 0, 0, 0, 0, 0, '2020-08-06', '2020-08-06', 2, 0, 0, 1, 0, 0, '', 1, ''),
(9, 0, 2, 14, 0, 0, 0, '', 'Implantação de assinatura digital (Docusign) para membros da equipe e alguns membros de outros departamentos da empresa que possuem necessidade de assinar ou colher assinatura em documentos a fim de seguir fluxo de informação, registro em sistema, autorização de pagamentos, dentre outros, bem como evidências SOX.\nCom a melhoria ganhamos agilidade no fluxo das documentações e coleta de assinatura, bem como redução de papel.', '', '', 101, 1040, 0, 0, 0, 0, '2020-08-13', '2020-08-13', 2, 0, 0, 1, 0, 0, '', 0, ''),
(10, 0, 2, 0, 0, 0, 0, '', 'Durante o fechamento contábil, as contas contábeis para conciliações são divididas entre áreas e pessoas. Para garantir que os saldos contábeis foram conclusos, os responsáveis me enviam por email uma planilha ou print screen das contas de sua responsabilidade, informando o saldo final. Antes, eu tinha que entrar conta por conta, verificar o saldo final e também perguntar aos responsáveis se estava tudo “ok”.\nIsso facilita o meu controle, bem como garante que nenhuma conta contábil ficou pendente de análises.\nAtravés desse procedimento, eu consigo monitorar, acompanhar e gerenciar o tempo no fechamento e a acuracidade das informações. ', '', '', 101, 0, 0, 0, 0, 0, '2020-08-13', '2020-08-13', 2, 0, 0, 1, 0, 0, '', 0, ''),
(11, 0, 4, 0, 0, 0, 0, '', 'Tubulação de água de quench aquecida para peletizador 2, foi feito isolamento para evitar queimadura.', '', '', 1076, 1120, 1081, 0, 0, 0, '2020-08-13', '2020-08-13', 2, 0, 0, 1, 0, 0, '', 0, ''),
(12, 0, 4, 0, 0, 0, 0, '', 'Estação de reprocesso de B.B’s  linha 3 , foi adaptado viga U com material de descarte para evitar que B.B’s rasguem', '', '', 1076, 1158, 1153, 0, 0, 0, '2020-08-13', '2020-08-13', 2, 0, 0, 1, 0, 0, '', 1, ''),
(13, 0, 4, 0, 2400, 0, 0, '', 'Atualizar procedimento I-SSMA-008, que descreve a necessidade de fornecer bebida isotônica para trabalhadores em recinto confinado, porém, instruído pelo Médico do trabalho que não o fizesse, por questões de saúde.', '', '', 1087, 0, 0, 0, 0, 0, '2020-08-13', '2020-08-13', 2, 0, 0, 1, 0, 0, '', 1, ''),
(14, 0, 2, 0, 0, 0, 0, '', 'Montagem e distribuição de uma planilha mensal de preços atualizados de matérias primas e embalagens utilizadas pela Orion Engineered Carbons - Paulínia. Objetivo: Melhorar o fluxo, atualização e centralização das informações', '', '', 1042, 0, 0, 0, 0, 0, '2020-08-17', '2020-08-17', 2, 0, 0, 1, 0, 0, '', 1, ''),
(15, 0, 2, 12, 0, 0, 0, '', 'Centralização das Especificações das matérias primas e embalagens utilizadas pela Orion\nEngineered Carbons – Paulínia em uma única pasta na Rede\nObjetivo: As especificações estavam divididas pelas áreas, dificultando a localização nas \nauditorias e envio para os fornecedores', '', '', 1042, 1094, 0, 0, 0, 0, '2020-08-17', '2020-08-17', 2, 0, 0, 1, 0, 0, '', 0, ''),
(16, 0, 2, 12, 0, 0, 0, '', 'Criação e implementação do Formulário de Exceção em Compras na planta de Paulínia.\nObjetivo: Flexibilizar e agilizar alguns processos de compras onde, devido justificativas\ndos requisitantes e com a aprovação da gerência responsável, exclui-se a necessidade de  \nmais cotações para comparativos e/ou escolha de uma proposta não vencedora do BID.\n', '', '', 1042, 0, 0, 0, 0, 0, '2020-08-17', '2020-08-17', 2, 0, 0, 1, 0, 0, '', 0, ''),
(17, 0, 2, 96, 0, 0, 0, '', 'Durante o mês de Agosto/ 2020 onde estamos com estoque zerado e muitos volumes de carregamento realizar o revezamento de jornada de trabalho na logística para atendimento ao cliente, não gerando horas extras. ', '', '', 1062, 1064, 0, 0, 0, 0, '2020-08-19', '2020-08-19', 2, 0, 0, 1, 0, 0, '', 0, ''),
(18, 0, 2, 0, 0, 0, 0, '', 'Os Check List de Conferência ficarem impressos em nossa sala e enviados na quantidade correta da programação de carregamento.\nAntigamente ficava algumas folhas impressas na doca com acúmulo de sujeira e não tinha um controle de quando estava acabando. ', '', '', 1136, 1064, 0, 0, 0, 0, '2020-08-26', '2020-08-26', 2, 0, 0, 1, 0, 0, '', 0, ''),
(19, 0, 4, 0, 0, 0, 0, '', 'Estive acompanhando o pessoal da montagem de andaime (ISOLAINE), e verifiquei que na atividade de adequar o piso (tabuas de madeira), os mesmo precisão realizar vários recortes. _x000D_\nOs recortes são feitos manualmente com cerrote (em péssimo estado), e além de dificultar o trabalho, leva muito tempo e cansaço físico (ergonomia)._x000D_\n_x000D_\nUma serra manual a bateria ajudaria em muito a realização dessa atividade, tendo em vista a demanda de trabalho dos mesmo. _x000D_\n_x000D_\nPesquisei e segue abaixo alguns links de tipos diferentes de ferramenta que os mesmos podem utilizar para realizar melhor esta atividade. _x000D_\n', '', '', 1149, 0, 0, 0, 0, 0, '2020-08-31', '2020-08-31', 2, 0, 0, 1, 0, 0, '', 0, ''),
(20, 0, 4, 50, 0, 0, 0, '', 'A corrente que segura a porta do banheiro masculino, ao lado do Ambulatório, chicoteia ao abrir a porta, foi instalado aparato que “prende” a corrente enquanto não estiver utilizando.', '', '', 1087, 0, 0, 0, 0, 0, '2020-09-01', '2020-09-01', 2, 0, 0, 1, 0, 0, '', 0, ''),
(21, 0, 2, 0, 0, 0, 0, '', 'O cabo terra das graneleiras só tem no chão, foi instalado mais 4 pontos na estrutura da escada de acesso facilitando assim a parte operacional, não sendo necessário o operador descer da passarela para conectar o cabo no caminhão, esta operação ficou mais fácil e diminuindo o tempo de carregamento do operador. ', '', '', 1081, 1154, 1152, 0, 0, 0, '2020-09-03', '2020-09-03', 2, 0, 0, 1, 0, 0, '', 2, ''),
(22, 0, 2, 150, 0, 0, 0, '', 'Fabricar dispositivo para diminuir espaço na junta de saída entre peletizador e bica da linha 3. Facilidade de manutemçao, limpeza e operação.', '', '', 1066, 0, 0, 0, 0, 0, '2020-09-06', '2020-09-06', 2, 0, 0, 1, 0, 0, '', 0, ''),
(23, 0, 2, 250, 0, 0, 0, '', 'Criação de planilha com máscara para copiar e colar no SAP a inclusão diária das taxas de câmbio.\nEsta é atualizada automaticamente após salvar arquivo gerado no site do Bacen e salvo na pasta ( L:FinanceiroPtax Diária - Inclusão SAP ) e com controle de datas para evitar erros.\n', '', '', 1058, 0, 0, 0, 0, 0, '2020-09-10', '2020-09-10', 2, 0, 0, 1, 0, 0, '', 0, ''),
(24, 0, 2, 4, 0, 0, 0, '', 'Foi criada uma máscara para copiar e colar no SAP na efetivação de baixa manual de contas a pagar e lançamentos dos extratos bancários diariamente.', '', '', 1058, 0, 0, 0, 0, 0, '2020-09-10', '2020-09-10', 2, 0, 0, 1, 0, 0, '', 0, ''),
(25, 0, 2, 4, 0, 0, 0, '', 'Criação de variante na FBL1N (SAP) para geração mensal do relatório de pagamentos efetuados no mês com retenção de PCC para conferência do Carlos Canhameiro', '', '', 1058, 0, 0, 0, 0, 0, '2020-09-10', '2020-09-10', 2, 0, 0, 1, 0, 0, '', 0, ''),
(26, 0, 2, 0, 0, 0, 0, '', 'Criação de variante na FBL5N para facilitar o controle do cliente Titan Pneus na modalidade de Risco Sacado.', '', '', 1058, 0, 0, 0, 0, 0, '2020-09-10', '2020-09-10', 2, 0, 0, 1, 0, 0, '', 0, ''),
(27, 0, 2, 2, 0, 0, 0, '', 'A planilha busca no arquivo do Banco Bradesco as informações dos boletos pagos, na base gerada da FBL5N (SAP – NFs em aberto) e compila numa planilha base. Após atualização dos dados gera uma máscara para copiar e colar no SAP e efetivar a baixa.', '', '', 1058, 0, 0, 0, 0, 0, '2020-09-10', '2020-09-10', 2, 0, 0, 1, 0, 0, '', 0, ''),
(28, 0, 2, 84, 0, 0, 0, '', 'Criação de planilha para baixas de clientes com pagamentos efetuados via depósito bancário e lançamentos de recebimentos diversos.', '', '', 1058, 0, 0, 0, 0, 0, '2020-09-10', '2020-09-10', 2, 0, 0, 1, 0, 0, '', 0, ''),
(29, 0, 2, 63, 0, 0, 0, '', 'Melhoria planilha de controle – Titan Pneus. Criação de coluna com histórico para geração de ND e saldos. ', '', '', 1058, 0, 0, 0, 0, 0, '2020-09-10', '2020-09-10', 2, 0, 0, 1, 0, 0, '', 0, ''),
(30, 0, 2, 15, 0, 0, 0, '', 'Criação de campos personalizados no DocuSign para agilizar o envio de documentos para aprovação', '', '', 1058, 0, 0, 0, 0, 0, '2020-09-10', '2020-09-10', 2, 0, 0, 1, 0, 0, '', 0, ''),
(31, 0, 2, 2, 0, 0, 0, '', 'Criação de uma planilha de modelo de lançamentos de ganhos ou perdas referente NDF (com ligação ao controle já existe de Hedge) no SAP afim de agilizar e evitar erro. ', '', '', 1058, 0, 0, 0, 0, 0, '2020-09-10', '2020-09-10', 2, 0, 0, 1, 0, 0, '', 0, ''),
(32, 0, 2, 6, 0, 0, 0, '', 'Criação de uma coluna na planilha de controle de Hedge para salvar os contratos assinados – arquivos com nomes específicos para facilitar a procura se necessário. ', '', '', 1058, 0, 0, 0, 0, 0, '2020-09-10', '2020-09-10', 2, 0, 0, 1, 0, 0, '', 0, ''),
(33, 0, 4, 3, 0, 0, 0, '', 'Mudar a posição do extintor de combate á incêndio que fica em frente ao Ciclone, para uma posição ( 2 vigas á frente), onde não seja atingido por vazamento de negro de fuma em para e partida de linha, podendo assim danificar o equipamento, gerando mais custo de manutenção do mesmo. ', '', '', 1149, 0, 0, 0, 0, 0, '2020-09-10', '2020-09-10', 2, 0, 0, 1, 0, 0, '', 0, ''),
(34, 0, 4, 0, 200, 0, 0, '', 'Demarcar no solo a distância segura de 1,5 m, na formação de fila para entrar no restaurante na hora das refeições. ', '', '', 1149, 0, 0, 0, 0, 0, '2020-09-10', '2020-09-10', 2, 0, 0, 1, 0, 0, '', 0, ''),
(35, 0, 1, 0, 0, 0, 0, '', 'Foi recuperado dois equipamentos ( piloto ) que são usados no acendimento dos reatores das linha 1-2-3 pois o mesmo pelo fabricante não tinha possibilidade de recuperação, foi feito teste em banca no dia 28/08/2020 o mesmo funcionou perfeitamente, dia 09/09/2020 foi instalado no reator da linha 2 com o seu funcionamento normal equipamento aprovado em bancada e em campo, o equipamento tem o custo aproximadamente R$ 28.500 mais o custo de importação de cada um deles.', '', '', 1071, 1066, 0, 0, 0, 0, '2020-09-10', '2020-09-10', 2, 0, 0, 1, 0, 0, '', 1, ''),
(36, 0, 2, 5, 57000, 0, 0, '', 'Planejar e imprimir as OSs semanais e quinzenais apenas uma vez por mês. Treinar os manutentores para o apontamento correto.\n40% redução em impressão, economizando toner e papel. 60% redução de tempo no planejamento de manutenção.', '', '', 1072, 0, 0, 0, 0, 0, '2020-09-10', '2020-09-10', 2, 0, 0, 1, 0, 0, '', 0, ''),
(37, 0, 2, 0, 5000, 0, 0, '', 'Entupimento constante  acima da rotativa do reprocesso de BB’s linha 3, instalado ponto de ar para desobstruir,  quando for necessario.', '', '', 1076, 1158, 0, 0, 0, 0, '2020-09-15', '2020-09-15', 2, 0, 0, 1, 0, 0, '', 0, ''),
(38, 0, 2, 0, 10000, 0, 0, '', 'Alterar no formulário de integração o campo para registro da CTPS para CPF', '', '', 1109, 1041, 0, 0, 0, 0, '2020-09-17', '2020-09-17', 2, 0, 0, 1, 0, 0, '', 0, ''),
(39, 0, 2, 0, 0, 0, 0, '', 'Registrado no celular da produção o contato da Air Liquid via Whatsapp.', '', '', 1087, 0, 0, 0, 0, 0, '2020-09-18', '2020-09-18', 2, 0, 0, 1, 0, 0, '', 0, ''),
(40, 0, 4, 0, 0, 0, 0, '', 'Solicitar à Prefeitura de Paulínia a iluminação e sinalização na via de acesso à Orion e demais empresas', '', '', 1109, 0, 0, 0, 0, 0, '2020-09-22', '2020-09-22', 2, 0, 0, 1, 0, 0, '', 0, ''),
(41, 0, 1, 0, 0, 0, 0, '', 'Adequar os suportes de sabonete desengraxante nos vestiários, trancando-os para que os mesmos não possam ser abertos ou retirado a tampa para que se utilize de maneira inadequada', '', '', 101, 0, 0, 0, 0, 0, '2020-09-22', '2020-09-22', 2, 0, 0, 1, 0, 0, '', 0, ''),
(42, 0, 2, 0, 300, 0, 0, '', 'Melhorias na planilha de lançamento do ajuste Comgás para facilitar a leitura no lançamento contábil. Inclusão da coluna “Chave de Lançamento” e aplicação de fórmula sobre o valor para distinção do Débito e Crédito.', '', '', 101, 1056, 0, 0, 0, 0, '2020-09-23', '2020-09-23', 2, 0, 0, 1, 0, 0, '', 0, ''),
(43, 0, 2, 0, 0, 0, 0, '', 'Elaboração de planilha que otimiza valores de mútuos de veículos a ser lançado no SAP. Com a planilha, os valores são inseridos nas respectivas despesas e já traz os valores e outras informações a serem consideradas para lançamento, gerando assim ganho de tempo, padronização e conhecimento para outros membros do departamento.', '', '', 101, 0, 0, 0, 0, 0, '2020-09-23', '2020-09-23', 2, 0, 0, 1, 0, 0, '', 0, ''),
(44, 0, 2, 26, 0, 0, 0, '', 'Instalado sistema de limpeza para linha de vacuo dos 05 compartimentos do Silo 1501 e 05 compartimentos do Silo 2501', '', '', 1083, 0, 0, 0, 0, 0, '2020-09-24', '2020-09-24', 2, 0, 0, 1, 0, 0, '', 0, ''),
(45, 0, 2, 0, 0, 0, 0, '', 'Elaboração de planilha que otimiza lançamentos no SAP de invoices de serviços compartilhados e depreciation rebill.', '', '', 101, 0, 0, 0, 0, 0, '2020-09-25', '2020-09-25', 2, 0, 0, 1, 0, 0, '', 0, ''),
(46, 0, 2, 30, 0, 0, 0, '', 'Instalar haste nas válvulas de descarga dos compressores 5300,5310,5320,5330, para facilitar manobras em caso de manutenção dos mesmos.', '', '', 1083, 0, 0, 0, 0, 0, '2020-10-01', '2020-10-01', 2, 0, 0, 1, 0, 0, '', 0, ''),
(47, 0, 2, 36, 0, 0, 0, '', 'Implementação de um novo modelo de relatório de turno. \nNo modelo anterior, os analistas preenchiam um relatório no modelo “word”, convertiam em “pdf” e depois enviavam por e-mail para todos da equipe do laboratório.\nNovo modelo facilita preenchimeto e está disponivel na rede.\n', '', '', 1090, 1094, 0, 0, 0, 0, '2020-10-01', '2020-10-01', 2, 0, 0, 1, 0, 0, '', 0, ''),
(48, 0, 4, 100, 0, 0, 0, '', 'Construir um abrigo para o local de armazenamento de cilindros. Atualmente os clindros ficam ao relento o que acelera a deterioração dos mesmos. Cilindro deteriorado (enferrujado) pode causar acidentes.', '', '', 1066, 0, 0, 0, 0, 0, '2020-10-01', '2020-10-01', 2, 0, 0, 1, 0, 0, '', 0, ''),
(49, 0, 1, 0, 0, 0, 0, '', 'Substituir as bombas de captação da lagoa Camberra por tipo sapo da Schneider.\nManutençáo mais barata (30k vs 4,5k), sem contar os tempos envolvidos.', '', '', 1066, 1072, 1158, 0, 0, 0, '2020-10-02', '2020-10-02', 2, 0, 0, 1, 0, 0, '', 0, ''),
(50, 0, 4, 0, 51000, 0, 0, '', 'Comprar um carrinho de transporte de cilindros de gases de solda. Atualmente os cilindros são transportados em um carrinho de carga que exige o levantamento do cilindro, que é pesado. Com o carrinho adequado melhorará a ergonomia e agilizará a operação', '', '', 1066, 0, 0, 0, 0, 0, '2020-10-05', '2020-10-05', 2, 0, 0, 1, 0, 0, '', 0, ''),
