(52, 0, 4, 50, 0, 0, 0, '', 'Criar dispositivo para transporte de materias com empilhadeira para até 2 Ton. Eliminar risco de queda de equipamentos no trasporte com empilhadeiras.', '', '', 1066, 0, 0, 0, 0, 0, '2020-10-05', '2020-10-05', 2, 0, 0, 1, 0, 0, '', 0, ''),
