(321, 0, 4, 0, 0, 0, 0, '', 'Feito melhoria caixa de ligação de alimentação dos poste de iluminação viária, quando chovia entrava Água ocasionando curto-circuito e desligando a iluminação', '', '', 1071, 1154, 1150, 0, 0, 0, '2021-11-08', '2021-11-08', 2, 0, 0, 1, 0, 0, '', 0, ''),
(322, 0, 2, 0, 0, 0, 0, '', 'Criado KPIs novos que realmente avaliem se as análises de falha estão sendo executadas e sendo eficazes. \nRevisão do processo de tratativa de anomalias em equipamentos;\nFoi reescrito o processo junto a todo time de manutenção, determinado responsáveis em caso de ausência de algum integrante do time e divulgado entre manutenção e operação.\nEste novo processo vai evitar falhas que sinalizam antes de acontecer.', '', '', 1069, 1072, 0, 0, 0, 0, '2021-11-05', '2021-11-05', 2, 0, 0, 1, 0, 0, '', 0, '');
INSERT INTO `kaizen` (`id_kaizen`, `categoria_kaizen`, `tipo_kaizen`, `tempo_kaizen`, `custo_kaizen`, `reducao_kaizen`, `destaque_kaizen`, `onde_kaizen`, `resultado_kaizen`, `imagem1_kaizen`, `imagem2_kaizen`, `colaborador_kaizen`, `colaborador1_kaizen`, `colaborador2_kaizen`, `colaborador3_kaizen`, `colaborador4_kaizen`, `lider_kaizen`, `datacadastro_kaizen`, `dataconclusao_kaizen`, `status_kaizen`, `admin_kaizen`, `pontos_kaizen`, `unidade_kaizen`, `setor_kaizen`, `outrosdep_kaizen`, `qual_kaizen`, `incidente_kaizen`, `obs_kaizen`) VALUES
(324, 0, 1, 0, 0, 0, 0, '', 'Estudo de rosca transportadora 1581, 2581\nEstudo aprofundado para limitar o escopo de reposição de itens para adequar ao budget. \nUma rosca nova custa 400k BRL e não estava prevista no budget de CAPEX. Com este estudo conseguimos reduzir os componentes realmente necessários e conseguimos fazer um reparo com 180k BRL, garantindo a confiabilidade do equipamento por pelo menos 2 anos.', '', '', 1069, 1066, 1067, 0, 0, 0, '2021-11-05', '2021-11-05', 2, 0, 0, 1, 0, 0, '', 0, ''),
(325, 0, 4, 0, 0, 0, 0, '', 'Monitoramento de danos no APH3\nCriação de matriz de comparação (dispositivo) para verificar se o APH esta deformando ou se toda tensão aplicada foi aliviada pela deformação apresentada.', '', '', 1069, 1155, 1158, 0, 0, 0, '2021-11-05', '2021-11-05', 2, 0, 0, 1, 0, 0, '', 0, ''),
(326, 0, 4, 0, 0, 0, 0, '', 'Desenvolvimento do fornecedor HAENKE para fornecer mangotes de óleo, pois os modelo corrente estava com baixa confiabilidade e vazamentos frequentes.', '', '', 1069, 1158, 1101, 0, 0, 0, '2021-11-05', '2021-11-05', 2, 0, 0, 1, 0, 0, '', 0, ''),
(327, 0, 2, 0, 0, 0, 0, '', 'Inserido a planilha de registro de temperaturas dos secadores no Sharepoint, para que todos os envolvidos possam visualizar com facilidade e fazer o acompanhamento online e em tempo real. Não há mais o risco de utilizar uma planilha desatualizada.', '', '', 1067, 1044, 0, 0, 0, 0, '2021-11-10', '2021-11-10', 2, 0, 0, 1, 0, 0, '', 0, ''),
(328, 0, 2, 0, 0, 0, 0, '', 'Modificar a medição de densidade de óleo D_3111.11 para temperatura transformando em T_3111.11 no SDCD.', '', '', 1085, 1073, 1037, 0, 0, 0, '2021-11-17', '2021-11-17', 2, 0, 0, 1, 0, 0, '', 0, ''),
(330, 0, 2, 0, 0, 0, 0, '', 'Para realização do teste de pH do negro de fumo, a garra não segura direito o frasco, varias vezes o frasco escorrega mesmo apertando bem, e vira perdendo a amostra.\nFoi colocado um emborrachado na garra que segura o frasco de vidro, evitando o atrito entre  vidro e o metal e risco de quebrar também.', '', '', 1095, 0, 0, 0, 0, 0, '2021-11-18', '2021-11-18', 2, 0, 0, 1, 0, 0, '', 0, ''),
(331, 0, 2, 0, 0, 0, 0, '', 'Após finalizar regeneração do abrandador, a bomba salmoura ficava sem permissão. Mesmo o operador reconhecendo o alarme no PLC, era necessário acessar outra tela e dar um reset geral para que a lógica ficasse ativa novamente para próxima regeneração. Unificar os botões de reconhecimento de alarme e reset de falhas.', '', '', 1074, 1075, 1080, 0, 0, 0, '2021-11-19', '2021-11-19', 2, 0, 0, 1, 0, 0, '', 0, ''),
(332, 0, 4, 0, 0, 0, 0, '', 'Foi configurado no SDCD Status para as válvulas de bloqueio do Reator e Retorno H_1111.13. Com isso ajudará o operador de sala identificar se as válvulas estão abertas e fechadas com mais facilidade e também ajudará muito na parte de segurança do equipamento com essa Automação.', '', '', 1065, 1071, 1157, 0, 0, 0, '2021-11-20', '2021-11-20', 2, 0, 0, 1, 0, 0, '', 0, ''),
(335, 0, 2, 0, 0, 0, 0, '', 'Foi instalado na base do APH da Linha 01  dois transmissores  de temperaturas  com indicação digital no local. Isso vai ajudar os operadores nas Rondas diárias e também no dia-a-dia doa manutentores no instruemento de medição de temperatura.', '', '', 1065, 1157, 1154, 0, 0, 0, '2021-11-20', '2021-11-20', 2, 0, 0, 1, 0, 0, '', 0, ''),
(337, 0, 2, 0, 0, 0, 0, '', 'Instalação de Flanges Soldados na Hot air Pipe e camâra de Combustão para facilitar a remoção da camâra de Combustão sem sacrificar a tubulação de ar quente. Obs: Linha 01', '', '', 1072, 1101, 0, 0, 0, 0, '2021-11-20', '2021-11-20', 2, 0, 0, 1, 0, 0, '', 0, ''),
(338, 0, 1, 0, 0, 0, 0, '', 'Foi instalado medição de vibração e temperatura no SDCD, dos sopradores, objetivo da idéia é detectar possível temperatura e vibração alta, e evitar paradas bruscas dos sopradores, pois quando há uma parada brusca ha risco de queda dos reatores.', '', '', 1076, 1065, 0, 0, 0, 0, '2021-11-22', '2021-11-22', 2, 0, 0, 1, 0, 0, '', 0, ''),
(339, 0, 2, 0, 0, 0, 0, '', 'O detector de movimento dos secadores  estão  atuando com frequência ocasionando a queda dos mesmos  foi verificado que é apenas sujeira sobre o sensor , sugiro que seja configurado a redundância destes sensores pois existem 2 em cada secador.', '', '', 1086, 1065, 1082, 0, 0, 0, '2021-11-24', '2021-11-24', 2, 0, 0, 1, 0, 0, '', 0, ''),
(340, 0, 4, 0, 0, 0, 0, '', 'Desenvolver e construir dispositivo organizador de cabos de alimentação de equipamentos elétricos, de modo que eles não obstruam a circulação de pessoas nem possam causas incidentes.', '', '', 1071, 1066, 1152, 0, 0, 0, '2021-11-27', '2021-11-27', 2, 0, 0, 1, 0, 0, '', 0, ''),
(341, 0, 2, 0, 0, 0, 0, '', 'Na C1 do reator onde fica o Pre-Quench tem uma caixa com refratário para proteger os ports de quench, foi instalado um tubo para que a agua de resfriamento quando utilizada, não entre em contato com o refratário, diminuindo a deterioração do material isolante. ', '', '', 1081, 0, 0, 0, 0, 0, '2021-11-29', '2021-11-29', 2, 0, 0, 1, 0, 0, '', 0, ''),
(342, 0, 2, 0, 0, 0, 0, '', 'Quando a necessidade de lavar a rotativa do peletizador, precisa inserir a lança na parte superior e acessar por escada para inverter a agua para a lança de limpeza, foi instalado um haste para a válvula nao sendo mais necessário subir e descer escada para acessar a válvula. ', '', '', 1081, 0, 0, 0, 0, 0, '2021-11-29', '2021-11-29', 2, 0, 0, 1, 0, 0, '', 0, ''),
