INSERT INTO `kaizen` (`id_kaizen`, `categoria_kaizen`, `tipo_kaizen`, `tempo_kaizen`, `custo_kaizen`, `reducao_kaizen`, `destaque_kaizen`, `onde_kaizen`, `resultado_kaizen`, `imagem1_kaizen`, `imagem2_kaizen`, `colaborador_kaizen`, `colaborador1_kaizen`, `colaborador2_kaizen`, `colaborador3_kaizen`, `colaborador4_kaizen`, `lider_kaizen`, `datacadastro_kaizen`, `dataconclusao_kaizen`, `status_kaizen`, `admin_kaizen`, `pontos_kaizen`, `unidade_kaizen`, `setor_kaizen`, `outrosdep_kaizen`, `qual_kaizen`, `incidente_kaizen`, `obs_kaizen`) VALUES
(490, 0, 2, 0, 0, 0, 0, 'Foi instalado um tubo no port 3 da lança de pre quench, quando vai retirar a lança é necessário abrir agua de limpeza da lança, para melhorar a remoção da mesma, facilitando a remoção da lança, e nao danifica o refratário. ', 'Com o prolongamento da port, agua não atinge a camada de refratário denso, a agua vai atingir somente a parte de refratário de sacrifício e evapora, nao danificando o refratário evitando paradas por super aquecimento da chapa da caixa de refratário   ', '', '', 1081, 0, 0, 0, 0, 0, '2022-08-18', '2022-08-31', 3, 1036, 0, 2, 1, 1, 'Ja instalado na L1', 0, ''),
(491, 0, 4, 0, 0, 0, 0, 'Instalação de espelhos retrovisores na lateral das empilhadeiras elétricas. \r\nO padrão de fábrica dela veio apenas com o retrovisor central, os da lateral amplia a visibilidade do operador. ', 'o retrovisor da lateral amplia a visibilidade do operador durante a movimentação. ', 'whatsapp_image_2022_08_18_at_14_16_29_1_.jpg', '', 1123, 1062, 0, 0, 0, 0, '2022-08-18', '2022-08-22', 2, 1045, 2, 2, 5, 2, '', 0, ''),
(492, 0, 2, 0, 0, 0, 0, 'AMPLIAR A IDENTIFICAÇÃO DO ARMÁRIO DE RETENÇÃO DAS AMOSTRAS DE ÓLEO RARO, ADICIONANDO AS OUTRAS PLANTAS DA PETROBRÁS.', '\r\nMELHORAR A ORGANIZAÇÃO NA RETENÇÃO DAS AMOSTRAS DE ÓLEO RARO, JÁ QUE É RECEBIDO ÓLEO DE DIFERENTES PLANTAS DE UM MESMO FORNECEDOR.\r\n', 'armario_antes.jpg', 'armario_depois.jpg', 1096, 1092, 0, 0, 0, 0, '2022-08-18', '2022-08-18', 2, 1039, 2, 2, 3, 2, '', 0, ''),
(493, 0, 2, 0, 0, 0, 0, 'Ciar pasta para organizar a Sala de Controle, pasta criada para armazenar as ações tomadas no Triconex.', 'Melhor visualização do local de guarda.', '', '', 1087, 0, 0, 0, 0, 0, '2022-08-19', '2022-08-31', 2, 1036, 2, 2, 1, 0, '', 0, ''),
(494, 0, 2, 0, 0, 0, 0, 'Realizado identificação de interruptor de iluminação da luminária da ensacadeira Hard', '', '', '', 1055, 0, 0, 0, 0, 0, '2022-08-19', '2022-08-31', 2, 1036, 2, 2, 13, 2, '', 0, ''),
(495, 0, 2, 0, 0, 0, 0, 'Suporte de lança para troca de bico da linha 03 não era adequado para todos tipos de lança, algumas lança não entrava no suporte foi realizado um corte para possibilitar uso de todas lança.', 'Aumento na segurança na atividade de troca de grau e diminuição no tempo.', '', '', 1077, 1076, 1086, 0, 0, 0, '2022-08-20', '2022-08-31', 2, 1036, 2, 2, 1, 2, '', 0, ''),
(496, 0, 3, 0, 0, 0, 0, 'Filtro de purga linha 01 (1322), controle da talha ficava jogado no piso do filtro podendo causa danos ao equipamento foi solicitado a colocação de um suporte para o controle.', 'Foi reduzido risco de danos ao equipamento, risco de acidentes como tropeço no cabo.', '', '', 1077, 0, 0, 0, 0, 0, '2022-08-20', '2022-08-31', 2, 1036, 2, 2, 1, 2, '', 0, ''),
(497, 0, 1, 0, 0, 0, 0, 'Instalar dispositivo nas lanças de gás de startup nos reatores 1,2 e 3.', 'Evitar que o tempo que a lança fica parada, entre algum tipo de contaminante como sujeiras e água da chuva no furo da lança, pois quando entra umidade ou contaminantes demora mais para acender a chama principal.', '', '', 1076, 1158, 0, 0, 0, 0, '2022-08-21', '2022-08-31', 2, 1036, 2, 2, 1, 2, '', 0, ''),
(498, 0, 1, 0, 0, 0, 0, 'Substituir válvulas de água do filtro de quench no reator 3 de globo para esfera.', 'Maior agilidade na inversão do filtro de água quando necessário evitando de \'derrubar\' a linha por temperatura alta.', '', '', 1076, 1158, 0, 0, 0, 0, '2022-08-21', '2022-08-31', 2, 1036, 2, 2, 1, 2, '', 0, ''),
(499, 0, 1, 0, 0, 0, 0, 'Inserir medidor de vazão alimentação da água para caldeira de recuperação. ', 'Mensurar o consumo de água potável e água de  processo para uma economia  ', '', '', 1086, 1065, 1082, 0, 0, 0, '2022-08-21', '2022-08-31', 2, 1036, 2, 2, 1, 2, '', 0, ''),
(500, 0, 2, 0, 0, 0, 0, 'Criar uma lista com revezamento mensal entre os analistas para realização da limpeza da capela 02 (onde fica o espectro e o densímetro 1).\r\nA equipe de limpeza contratada pela Orion não pode realizar a limpeza nesse local por conter materiais perigosos à saúde, portanto é uma área exclusiva de limpeza dos analistas. Por este fato, a capela tem permanecido por muito tempo suja.\r\n', 'O objetivo é que um analista, por mêsm fique com a responsabilidade de limpeza da capela, conforme uma escala criada com revezamento.\r\nNo seu mês designado, o analista faz uma limpeza mais minuciosa da capela (dos azulejos e equipamentos), e depois cuida apenas da manutenção dessa limpeza.\r\n', '', '', 1090, 0, 0, 0, 0, 0, '2022-08-21', '2022-09-02', 2, 1039, 2, 2, 3, 1, 'Todos com rodizio de funcionarios operando ou manuseando um sistema/equipamento.', 0, ''),
(501, 0, 4, 0, 0, 0, 0, 'Utilizar o balde de 14L para descarte de negro de fumo, na bancada da sala 5 (ao invés do balde de 20L).', 'O objetivo e reduzir o impacto na coluna com o carregamento e elevação de peso para descarte no Tob bin, e diminuir o risco de acidente por elevação de muito peso.', '', '', 1090, 0, 0, 0, 0, 0, '2022-08-21', '2022-09-02', 2, 1039, 2, 2, 3, 2, '', 0, ''),
(502, 0, 2, 0, 0, 0, 0, 'REALIZAR OS TESTES DE NORMALIZAÇÃO COM UMA FREQUÊNCIA MENSAL.\r\nUM ABSORTÔMETRO POR VEZ.', 'ESTES TESTES DE NORMALIZAÇÃO DOS ABSORTÔMETROS, SERÁ DE RESPONSABILIDADE DA TÉCNICA DE LABORATÓRIO.\r\nEM HORÁRIO ADIMINISTRATIVO.', '', '', 1096, 0, 0, 0, 0, 0, '2022-10-20', '2022-10-20', 2, 1082, 2, 2, 3, 2, '', 0, 'Castro,\r\n\r\nFavor ajustar o texto pois não é necessário criar uma escala, as análises ficarão sob responsabilidade da técnica de laboratório, com frequência mensal.'),
(503, 0, 3, 0, 0, 0, 0, 'FAZER O USO DE POTES PEQUENOS AO INVÉS DE BALDES GRANDES NAS COLETAS DE AMOSTRAS PARA REVALIDAÇÃO.', 'SÃO COLETADAS AS AMOSTRAS EM BALDES, GERANDO GRANDE QUANTIDADE DE NEGRO DE FUMO PARA DESCARTE.', '', '', 1096, 0, 0, 0, 0, 0, '2022-08-22', '2022-09-02', 2, 1039, 2, 2, 3, 0, '', 0, ''),
(504, 0, 4, 0, 0, 0, 0, 'FAZER A INSTALAÇÃO DA CAIXA DE TRAVAMENTO EM UM SUPORTE.', 'HOJE A CAIXA DE TRAVAMENTO SE ENCONTRA EM CIMA DA MESA.', '', '', 1096, 0, 0, 0, 0, 0, '2022-08-22', '2022-09-02', 2, 1039, 2, 2, 3, 0, '', 0, ''),
(505, 0, 4, 0, 0, 0, 0, 'Alteração do projeto de mangotes de óleo para utilização de proteção dumlock na extremidade de modo a evitar flexão excessiva e falha do mangote seguido de vazamento.', 'redução de cerca de 10 gensuits a menos por ano abertos para vazamento de óleo por falha de mangote', 'mangote_oleo_modelo_antigo.jpg', 'mangote_dumlock.jpg', 1069, 1158, 0, 0, 0, 0, '2022-08-23', '2022-08-23', 2, 1044, 2, 2, 4, 1, 'qualquer aplicação onde a flexão de tubo flexível seja um problema', 10, ''),
(506, 0, 2, 416, 16000, 0, 0, 'Substituição do modelo de roletes de transporte iniciais dos racks dinâmicos.\r\n', 'Serão instalados roletes, que são fabricados com um eixo no interior, isso fará com que não ocorra mais quebras dos parafusos de fixação, nos roletes existentes atualmente.\r\nIsso ira reduzir  o tempo o tempo utilizado na inspeção dos racks dinâmicos. \r\nAtualmente as inspeções são realizadas semanalmente, com dois profissionais. Com a substituição do modelos a periodicidade passará para 15 dias.', 'whatsapp_image_2022_08_24_at_13_35_17_.jpg', 'whatsapp_image_2022_08_24_at_13_00_29_.jpg', 1100, 1150, 1158, 0, 0, 0, '2022-08-24', '2022-08-25', 2, 1, 2, 2, 4, 1, 'Logística', 0, ''),
(507, 0, 2, 416, 0, 0, 0, 'Dashboard de controle e gestão de manutenção', 'Com o dashboard será possível termos um maior controle das atividades que são executadas na planta.\r\nDar subsídios para analises de indicadores de manutenção, MTTR,MTBF, DOWTIME.\r\nmapeamento de áreas operacionais e  equipamentos com maior numero de notas de serviços abertas.\r\nControle de histograma de mão de obra, entre outros...', '', 'capturar.jpg', 1100, 0, 0, 0, 0, 0, '2022-08-24', '2022-08-25', 2, 1, 2, 2, 4, 0, '', 0, ''),
(508, 0, 4, 0, 0, 0, 0, 'Instalar porta cadeados na sala de controle.', 'Melhorar organização e agilidade nas liberações de trabalho.', '20220824_145001.jpg', '20220824_144909.jpg', 1088, 1089, 0, 0, 0, 0, '2022-08-24', '2022-08-31', 2, 1036, 2, 2, 1, 0, '', 0, ''),
(509, 0, 2, 0, 0, 0, 0, 'Hoje, para liberação do óleo Raro, matéria prima é necessário lançar os valores do certificado na planilha (ODIS) para ver se todos os parâmetros estão dentro da especificação, após essa verificação, temos que assinar uma folha trazida pelos operadores, informando se esta ok ou não, para descarregar o produto, mas para assinar esse documento, temos que procurar o procedimentos Mp(matéria prima) ou ficha de especificação correspondente ao produto a ser liberado na pasta dentro do armário. ex-MP-qual-024-00(Óleo BTE)\r\nGostaria de introduzir na planilha Excel Odis, o numero da ficha de especificação, para diminuir o fluxo de trabalho, para que não seja mas necessário procurar nas pastas onde é arquivada.\r\n\r\n\r\n ', 'Diminuir o fluxo de trabalho, e centralizar informações importantes para liberação da matéria prima.', '', '', 1091, 0, 0, 0, 0, 0, '2022-08-25', '2022-09-02', 2, 1039, 2, 2, 3, 0, '', 0, ''),
(510, 0, 3, 0, 0, 0, 0, 'Aquisição de uma pistola graxeira elétrica com precisão de contagem em gramas para lubrificação de motores elétricos e mancais dos rolos dos secadores 1,2 e 3', 'Nos motores elétricos o ganho será na precisão  de gramas de graxa que cada motor pede para seu perfeito funcionamento, aumentando a sua vida útil pela lubrificação precisa.\r\n\r\nNos mancais dos rolos dos secadores o ganho é devido a precisão na quantidade do lubrificante evitando assim o desperdício do lubrificante com excesso e reduzindo seu consumo e valores de aquisição ', 'img_20220826_142053232.jpg', '', 1097, 1044, 0, 0, 0, 0, '2022-08-26', '2022-08-29', 2, 1044, 2, 2, 4, 1, 'Todos mancais e rolamentos que se faça lubrificação manual por pistola graxeira', 0, ''),
(511, 0, 2, 20, 0, 0, 0, 'Foi solicitado colocar no Picking List as informações no item Logistics Instructions para vir automaticamente na hora de gerar os Picking List.', 'Na hora de gerar os Picking List de carregamento não é necessário editar o item Logistics Instructions, as informações seguem automáticas.', 'logistics_instructions_.jpg', 'logistics_instructions_1_.jpg', 1064, 0, 0, 0, 0, 0, '2022-08-26', '2022-08-29', 2, 1045, 2, 2, 5, 2, '', 0, ''),
(512, 0, 2, 0, 0, 0, 0, 'Grupo no Teams LOG x MANUT para compartilhar com todos o status das empilhadeiras, prioridades, tratativas, ocorrências e follow up. ', '', 'grupo_teams_empilhadeiras.jpg', '', 1062, 0, 0, 0, 0, 0, '2022-08-30', '2022-08-30', 2, 1045, 2, 2, 5, 1, 'Alguns departamentos que tem prioridade de tratativas pode usar esse método.', 0, ''),
(513, 0, 4, 0, 0, 0, 0, 'Colocar uma porta de limitação para acesso de pessoas na doca onde tem o fluxo intenso de empilhadeiras. ', '', 'whatsapp_image_2022_08_29_at_14_17_34_.jpg', '', 1131, 0, 0, 0, 0, 0, '2022-08-30', '2022-08-30', 2, 1045, 2, 2, 5, 2, '', 0, ''),
(514, 0, 2, 0, 0, 0, 0, 'Instalação de ponto de vácuo próximo ao ventilador POS 3342 com a finalidade de manter a estação de reprocesso mais limpa.', 'Terá o objetivo de manter a estação de reprocesso mais limpa.', '', '', 1159, 1086, 1077, 0, 0, 0, '2022-09-01', '2022-10-04', 3, 1039, 0, 2, 1, 2, '', 0, ''),
(515, 0, 2, 0, 0, 0, 0, 'Demarcação no piso para bags, gaiolas e paletes nas estações de reprocesso da linha 3', 'Melhor organização e segurança', '', '', 1159, 1077, 1076, 0, 0, 0, '2022-09-01', '2022-09-09', 2, 1036, 2, 2, 1, 1, 'Nas estações de reprocesso das linhas 1, 2', 0, ''),
(516, 0, 2, 4, 0, 0, 0, 'Redução de lançamentos de MIGO para a conta de celulares.', 'Antes da melhoria era necessário mais de 40 lançamentos individuais por mês, pois era feito por cada celular corporativo.\r\nApós a análise constatar que os lançamentos iriam para a mesma conta contábil e centro de custo, foi reduzido para apenas um lançamento de MIGO no mês. Redução de em média 15-20 minutos de trabalho por mês.', 'antes_po_4500482425.jpg', 'depois_po_4500511456.jpg', 1141, 1056, 1059, 0, 0, 0, '2022-09-06', '2022-12-02', 2, 1040, 2, 2, 6, 2, '', 0, ''),
(517, 0, 2, 13, 0, 0, 0, 'Lançamento de solpags, RD\'s e RDV\'s via upload de contabilização no SAP.', 'Ao invés de lançar um documento por vez, é possível preencher a planilha de upload no excel, para cada modelo de lançamento, com as informações e lançar de uma vez só.\r\nA média de lançamento individual é de 3min/documento sendo que temos uma média anual de 800 documentos, totalizando 40 horas anuais de trabalho.\r\nVia upload, o tempo de lançamento por documento cai para 2 min/documento, totalizando 26,6 horas anuais de trabalho. Essa melhoria gera uma redução de 13,40 horas anuais.', 'solpags_para_lancamento.jpg', 'upload_solpags.jpg', 1141, 1058, 1057, 0, 0, 0, '2022-09-06', '2022-12-02', 2, 1040, 2, 2, 6, 1, 'Necessário análise da necessidade de cada área', 0, ''),
(518, 0, 2, 0, 0, 0, 0, 'Criação de um formulário contendo todas as informações inerentes a materiais de projetos. Incluindo o solicitante, o numero do projeto, a ordem de serviço e a descrição dos materiais relacionados quando possível.\r\nEste formulário será colocado no material.', 'Sem essa identificação, muitos dos itens não eram encontrados por seus solicitantes e as vezes utilizados por engano em outras aplicações.\r\nCom essa identificação completa, os responsáveis não perderão tempo ao encontrar e aplicar os materiais.', '', '20220823_162215.jpg', 1070, 1101, 0, 0, 0, 0, '2022-09-06', '2022-09-06', 2, 1044, 2, 2, 4, 2, '', 0, ''),
(519, 0, 2, 0, 0, 0, 0, 'Criar procedimento para que não necessite da abertura de LTS(liberação de trabalho seguro), para checagens/calibrações de alguns equipamentos que são periódicas no Laboratório.', 'Melhorar o fluxo de trabalho, já que após a implementação não será mas necessário a abertura da LTS.', '', '', 1091, 0, 0, 0, 0, 0, '2022-09-07', '0000-00-00', 4, 1082, 0, 2, 3, 2, '', 0, 'Anderson,\r\n\r\nPor favor, escrever o procedimento (ART - Analise de risco da tarefa) para que eu possa aprovar o KAIZEN.\r\nCaso precise de ajuda pode me procurar.'),
(520, 0, 2, 0, 0, 0, 0, 'Separador magnético, devido instalação da ensacadeira nova o painel que fica do lado do mesmo dificultando  a retira para  limpeza, assim tendo que remover uma  trava que tem  em cima, ficando livre para remover o separador magnético. ', '', '', '', 1055, 1081, 0, 0, 0, 0, '2022-09-09', '2022-09-16', 2, 1039, 2, 2, 13, 2, '', 0, ''),
(521, 0, 2, 5, 0, 0, 0, 'Foi solicitada a informação do pedido de compra/STO nas informações adicionais dos Ctes emitidos pelo fornecedor Toniato, referente à transporte de mercadoria importada.', 'Com essa informação adicionada no CTen ,ão é mais necessário buscar no sistema a NF de origem, para localizar o número do pedido. Temos em médias 150 Ctes a serem lançados no ano, gerando um tempo aproximado de busca do pedido de 2min por CTe.\r\n150x2=300min/ano > 5 horas de trabalho reduzidas no ano.\r\nColaborador que participou do kaizen: Vitória Gomes.', 'cte_71925_1_antes.jpg', 'cte_72020_1_depois.jpg', 1141, 0, 0, 0, 0, 0, '2022-09-13', '2022-12-02', 2, 1040, 2, 2, 6, 2, '', 0, ''),
(522, 0, 2, 0, 0, 0, 0, 'Novo controle de atualização em tempo real da cobertura de estoque dos itens de venda de PAA.', 'Redução do tempo de decisão na colocação das ordens de ensaque para controle de nível de silo (balanceamento entre os vários skus de venda do mesmo grade) / melhor acuracidade na tomada de decisão.\r\nVisão antecipada do que irá entrar em estoque obsoleto no mês seguinte e atuar preventivamente.', 'capturar_220915111201.jpg', '', 1045, 0, 0, 0, 0, 0, '2022-09-15', '2022-09-21', 2, 1036, 2, 2, 5, 2, '', 0, ''),
(523, 0, 2, 0, 0, 0, 0, 'Melhoria no MRP de embalagens que proporciona maior acurácia na decisão do volume das RC´s.', 'Maior acurácia na decisão do volume de compra de embalagens através de uma melhoria no MRP na qual considera o plano de produção ao invés do Forecast. Como itens de embalagens possuem demanda dependente, o cálculo de necessidade de reposição precisa considerar a sazonalidade do plano de produção ao invés do forecast de vendas (pois temos as paradas ao longo do ano)', '', '', 1045, 0, 0, 0, 0, 0, '2022-09-15', '2022-09-21', 2, 1036, 2, 2, 5, 2, '', 0, ''),
(524, 0, 2, 0, 0, 0, 0, 'Disponibilizado varal para estender pantufas ao invés de deixar as pantufas no piso', 'Melhor organização da área, reduz risco ergonômico ', '', '', 1041, 1149, 0, 0, 0, 0, '2022-09-19', '2022-09-21', 2, 1036, 2, 2, 10, 2, '', 0, ''),
(525, 0, 4, 0, 0, 0, 0, 'Temos uma doca que é usada para coleta seletiva que tem um desnível e fica agua empossada no local. ', 'Fazer o  nivelamento do piso para não ficar mais acumulo de água', 'melhoria_doca_interna_ensaque_nivelamento_do_p.jpg', '', 1062, 1122, 0, 0, 0, 0, '2022-09-20', '2022-09-20', 2, 1045, 2, 2, 5, 2, '', 0, ''),
(526, 0, 4, 0, 0, 0, 0, 'Estender a proteção do guard-rayl até a parede.', 'Eliminar o acesso dos motoristas naquele vão - pois alguns deles já passaram por ali. ', 'estender_guardrayl_ate_a_parede.jpg', '', 1062, 0, 0, 0, 0, 0, '2022-09-20', '2022-09-20', 2, 1045, 2, 2, 5, 2, '', 0, ''),
(527, 0, 2, 0, 0, 0, 0, 'Colocar mais Pó de Brita na área onde os caminhões acessam para descarga, tem algumas partes mais fundas.', 'Segurança na manobra das empilhadeiras para as descargas de embalagens. ', 'area_de_descarga_brita.jpg', '', 1062, 1135, 1139, 0, 0, 0, '2022-09-20', '2022-09-20', 2, 1045, 2, 2, 5, 2, '', 0, ''),
(528, 0, 4, 0, 0, 0, 0, 'Colocar limitador na parede ao lado dos racks - para que os bags e equipamentos que fiquem ali do lado não encostem e nem danifique a parede.', 'Irá limitar o acesso dos pallets para não danificar a parede. ', 'limitador_na_parede_ao_lado_do_rack.jpg', '', 1062, 1139, 0, 0, 0, 0, '2022-09-20', '2022-09-20', 2, 1045, 2, 2, 5, 2, '', 0, ''),
(529, 0, 4, 0, 0, 0, 0, 'Colocar na área da Logistica placa de instrução aos motoristas', 'Identificação visual para todos que acessarem a área', 'placa_motorista.jpg', '', 1130, 0, 0, 0, 0, 0, '2022-09-20', '2022-09-20', 2, 1045, 2, 2, 5, 2, '', 0, ''),
(530, 0, 4, 0, 0, 0, 0, 'Colocar Caixinhas de Bloqueio de Chave do Motorista: Na descarga da rua do silo / Na área da Brita / Na área de amarração', 'Bloqueio dos caminhões. ', '', '', 1130, 0, 0, 0, 0, 0, '2022-09-20', '2022-09-20', 2, 1045, 2, 2, 5, 2, '', 0, ''),
(531, 0, 2, 0, 0, 0, 0, 'Manutenção desenvolver um dispositivo (sugestão na foto) para tirar e colocar as réguas no sider.', 'Para facilitar de colocar e retirar as réguas dos veículos Sider. ', 'sugestao_dispositivo_para_reguas_kaizen_pedro.jpg', '', 1130, 1062, 1129, 0, 0, 0, '2023-01-19', '2023-05-04', 2, 1045, 2, 2, 5, 2, '', 0, 'Aguardar verificação de viabilidade'),
(532, 0, 4, 0, 0, 0, 0, 'Proteção de corrimão da escada de acesso a Logística esta com um \"canto vivo\" ', 'Colocar nova proteção para não ter risco de \"enroscar\" na área. ', 'escada_canto_vivo.jpg', '', 1130, 0, 0, 0, 0, 0, '2022-09-20', '2022-09-20', 3, 1045, 0, 2, 5, 0, '', 0, ''),
(533, 0, 4, 0, 0, 0, 0, 'Colocar na parte de cima outro batedor, assim, quando a carreta encostar na doca evita que danifique a parede de concreto.', 'Para proteger mais a parede pois as carretas não tem padrão de altura ', '', '', 1130, 0, 0, 0, 0, 0, '2022-09-20', '2022-09-20', 2, 1045, 2, 2, 5, 0, '', 0, ''),
