(535, 0, 4, 0, 0, 0, 0, 'Secador da linha 01, foi implementado um funil para coletar óleo que sai do motor do secador antes o coletor despejava óleo na tampa do tambor causando perca de contenção.', 'Reduzido perca de contenção de óleo.', '', '', 1077, 1076, 1159, 0, 0, 0, '2022-09-24', '2022-10-04', 2, 1039, 2, 2, 1, 1, 'Secador 02/03', 0, ''),
(536, 0, 2, 0, 0, 0, 0, 'Utilização de copo descartável (plástico), para coletar o óleo raro do frasco metálico e transferir para os cadinhos de porcelana. ', 'Facilitar o manuseio do óleo raro e evitar respingos do mesmo sobre a balança de pesagem.', '', '', 1093, 0, 0, 0, 0, 0, '2022-09-26', '2022-09-28', 2, 1082, 2, 2, 3, 2, '', 0, ''),
(537, 0, 2, 6, 0, 0, 0, 'Automatização do controle de risco sacado, utilizando os relatórios disponível pelo Banco Itau e SAP.\r\nConferência e geração do relatório efetuados no excel - Power Query', 'Redução no tempo de execução e mitigação de erros', 'annotation_2022_09_27_145338.jpg', 'annotation_2022_09_27_145532.jpg', 1058, 0, 0, 0, 0, 0, '2022-09-27', '2022-12-02', 2, 1040, 2, 2, 6, 1, '', 0, ''),
