(959, 0, 2, 0, 0, 0, 0, 'Identificado botoeira desabilitado em campo ', 'Ajuda na operação do dia a dia, que aquela botoeira esta dasabilitada.', '1695015823615_230918031152.jpg', '1695015823538_230918031153.jpg', 1162, 1074, 0, 0, 0, 0, '2023-09-18', '2023-10-25', 3, 1039, 0, 2, 1, 0, '', 0, ''),
