(1175, 0, 0, 0, 0, 0, 0, 'Revisar Procedimentos da Produção', 'Foi revisado procedimentos de Paradas de Linhas ', '', '', 1080, 1074, 1075, 0, 0, 0, '2024-06-28', '2024-06-28', 2, 1039, 2, 2, 1, 0, '', 0, ''),
(1176, 0, 2, 0, 0, 0, 0, 'Fazer trend bomba 3102 (água resfriamento da lança central Reator 03)  \r\n', 'Bomba não tem trend de indicação de status', '', '', 1080, 1074, 1075, 0, 0, 0, '2024-06-28', '2024-06-28', 2, 1039, 2, 2, 1, 0, '', 0, ''),
