(1224, 0, 2, 0, 0, 0, 0, 'instalado suporte para apagador e caneta no quadro de bloqueio  ', 'Organização do local. ', 'img_20240710_134549_240725043715.jpg', 'img_20240725_161809_240725043717.jpg', 1075, 1074, 1080, 0, 0, 0, '2024-07-25', '2024-07-25', 2, 1039, 2, 2, 1, 0, '', 0, ''),
(1225, 0, 4, 0, 0, 0, 0, 'Feito rampa de cimento no degrau da cabine de gases do laboratório', 'Evitar acidentes com quedas de cilindros de gases, no manuseio e troca dos mesmos.', '', '', 1093, 0, 0, 0, 0, 0, '2024-07-25', '2024-08-13', 2, 1082, 2, 2, 3, 2, '', 0, ''),
(1226, 0, 1, 0, 0, 0, 0, 'Foi instalado na lança de pulso do OPH linha 1 bico 40.', 'Melhorar a atomização de água no momento do pulso, minimizando impactos, pois a água da lança de pulso era sem bico  entrando um jato seco no momento do pulso.', '', '', 1076, 1163, 1152, 0, 0, 0, '2024-07-27', '2024-08-01', 2, 1039, 2, 2, 1, 1, '', 0, ''),
(1227, 0, 2, 0, 0, 0, 0, 'Foi feito 2 coletor de amostra dos peletizadores da linha 1 com limitador móvel que evita bater na estrutura.', 'Mais agilidade na operação de coleta de amostra.', '', '', 1037, 1152, 1158, 0, 0, 0, '2024-07-29', '2024-08-01', 2, 1039, 2, 2, 1, 2, '', 0, ''),
(1228, 0, 2, 0, 0, 0, 0, 'Verificamos um grande problema nas válvulas da Samson de identificação dos obturadores e sede por serem codigos samson destintos e optamos em comprar kits por valvula facilitando a identificação, maior facilidade na compra e maior facilidade na hora de identificar no estoque.', 'Verificamos um grande problema nas válvulas da Samson de identificação dos obturadores e sede por serem codigos samson destintos e optamos em comprar kits por valvula facilitando a identificação, maior facilidade na compra e maior facilidade na hora de identificar no estoque.', '', '', 1153, 1164, 1070, 0, 0, 0, '2024-07-30', '2024-07-31', 2, 1044, 2, 2, 4, 1, 'Compras', 0, ''),
(1229, 0, 1, 0, 14370, 0, 0, 'Comprando kit de válvula de processo da Samson identificamos que eles estavam enviando peças que não usamos no ato da manutenção e foi solicitado a Samson que retirasse esses materiais, ficando apenas a SEDE  e o OBTURADOR.', 'redução do custo de um kit e redução de lead time de entrega, redução de espaço na hora do armazenamento do material.', 'samson.jpg', '', 1153, 1164, 1070, 0, 0, 0, '2024-07-30', '2024-07-31', 2, 1044, 2, 2, 4, 1, 'Compras', 0, ''),
(1230, 0, 2, 0, 0, 0, 0, 'Alteração das identificações das pastas na área de Suprimentos', 'Padronização e melhor identificação visual das pastas.', 'antes__240730114228.jpg', 'depois__240730114228.jpg', 1164, 0, 0, 0, 0, 0, '2024-07-30', '2024-08-01', 2, 1042, 2, 2, 2, 1, 'Todos que possuem pastas', 0, ''),
(1231, 0, 4, 0, 0, 0, 0, 'Foi configurado 2 telas do computador comunitário da sala de controle para visualização das câmeras de monitoramento das áreas do RARO e matérias-primas. ', 'Visualização muito mais nítida e precisa das áreas do RARO e matérias-primas, sendo mais efetivo na identificação de possíveis vazamentos.', '', 'whatsapp_image_2024_07_30_at_14_28_10_.jpg', 1039, 1061, 0, 0, 0, 0, '2024-07-30', '2024-07-30', 2, 1036, 2, 2, 3, 2, '', 0, ''),
(1232, 0, 2, 0, 0, 0, 0, 'Realizado identificação das linhas de nitrogênio na saída do tanque  1216/2216 para linhas 1/2/3', 'Com a identificação das linhas vai ficar mais fácil para bloquear numa parada diminuindo  risco de bloquei errado ', '', '', 1077, 1076, 1086, 0, 0, 0, '2024-08-01', '2024-08-01', 2, 1039, 2, 2, 1, 0, '', 0, ''),
(1233, 0, 2, 0, 0, 0, 0, 'Identificação da linha de retorno de agua do choke próximo da valvula de 3 vias ', 'Com a identificação da linha vai ajudar nas manobra de interligação da frigel com o choke ', '', '', 1077, 1076, 1086, 0, 0, 0, '2024-08-01', '2024-08-01', 2, 1039, 2, 2, 1, 0, '', 0, '');
INSERT INTO `kaizen` (`id_kaizen`, `categoria_kaizen`, `tipo_kaizen`, `tempo_kaizen`, `custo_kaizen`, `reducao_kaizen`, `destaque_kaizen`, `onde_kaizen`, `resultado_kaizen`, `imagem1_kaizen`, `imagem2_kaizen`, `colaborador_kaizen`, `colaborador1_kaizen`, `colaborador2_kaizen`, `colaborador3_kaizen`, `colaborador4_kaizen`, `lider_kaizen`, `datacadastro_kaizen`, `dataconclusao_kaizen`, `status_kaizen`, `admin_kaizen`, `pontos_kaizen`, `unidade_kaizen`, `setor_kaizen`, `outrosdep_kaizen`, `qual_kaizen`, `incidente_kaizen`, `obs_kaizen`) VALUES
(1234, 0, 2, 0, 0, 0, 0, 'Usamos um becker de plástico para guardar as peneiras do grit após o uso, ao colocar as peneiras no becker observei que estava causando impacto de uma na outra, podendo danificar a malha da peneira.', 'Foi trocado o becker por outra peça de plástico onde não causa impacto na hora de armazenar as peneiras.', '', '', 1096, 0, 0, 0, 0, 0, '2024-08-02', '2024-09-02', 2, 1082, 2, 2, 3, 0, '', 0, ''),
(1235, 0, 3, 0, 0, 0, 0, 'Realizado a revisão do procedimento PAA-COM-004 onde foi inserido sobre os passos a serem seguidos em caso de homologação de produto para cliente. Antes essa orientação não está oficialmente redigida, causando falha na comunicação entre os departamentos, podendo interferir na satisfação do cliente final.\r\nTambém foi reavaliada as informações importantes que devem conter na planilha de análise crítica do cliente, para consulta das outras áreas.', 'Como ganho se tem maior robustez no processo de homologação de produto e de envio de produto ao cliente, bem como melhora na comunicação entre as áreas envolvidas.', '', '', 1092, 1064, 1050, 0, 0, 0, '2024-08-02', '2024-08-13', 2, 1082, 2, 2, 3, 1, 'Todas', 0, ''),
(1236, 0, 3, 0, 0, 0, 0, 'No processo de homologação de produto não havia direcionamento de quais análises deveriam ser realizadas.', 'Procedimento revisado e inseridas as análises mínimas necessárias para homologação e indicação dos demais testes dependendo do caso.\r\nTambém foi adicionada informação de que é necessário inserir no sistema SAP os valores encontrados na amostra.', '', 'kaizen_homologacao_de_produto.jpg', 1094, 1092, 0, 0, 0, 0, '2024-08-02', '2024-08-13', 2, 1082, 2, 2, 3, 2, '', 0, ''),
(1237, 0, 2, 0, 0, 0, 0, 'Criado campo de identificação para Iodo da Merck e para o Iodo da Sigma na planilha de checagem.', 'Facilitar na identificação da solução de iodo que irá ser preparada e sua pesagem de iodo ideal, pois requer massas diferentes para o prepara da solução. Também identificar a performance de cada reagente e sua concentração.', '', '', 1093, 1094, 0, 0, 0, 0, '2024-08-03', '2024-09-02', 2, 1082, 2, 2, 3, 2, '', 0, ''),
(1238, 0, 2, 0, 0, 0, 0, 'Na rotina comercial utilizamos materiais de apoio com informações técnicas dos produtos para guiar as indicações de produtos e suporte ao cliente.\r\nExistem vários catálogos que apresentam as principais características dos produtos e detalhes de aplicação, porém estes materiais de apoio não contemplam os produtos da linha PBR.\r\nForam coletadas as principais informações técnicas dos produtos disponíveis nas fichas técnicas e time técnico foi consultado para obtenção de demais informações.', 'Foi criada uma tabela chamada \"PBR - Technical Information\" contendo as principais características dos produtos PBR G, PBR 60 e PBR 300.\r\nEste documento será utilizado na rotina comercial para consultas rápidas, tornando o processo mais assertivo e rápido.', '', '', 1175, 1094, 1092, 0, 0, 0, '2024-08-06', '2024-10-02', 2, 1, 2, 3, 9, 1, 'Compras, Customer Service, Administrativo, Operações ...', 0, ''),
(1239, 0, 2, 0, 0, 0, 0, 'Foi adicionado na planilha do ODIS, o número dos procedimentos de cada fornecedor de ÓLEO RARO .', 'Toda vez que precisa lançar um lote novo, é necessário verificar o número na pasta de arquivo.\r\nCom o número na planilha, já se faz o preenchimento sem precisar do auxílio da pasta.', '', 'odis.jpg', 1096, 1090, 0, 0, 0, 0, '2024-08-11', '2024-09-02', 2, 1082, 2, 2, 3, 2, '', 0, ''),
(1240, 0, 2, 0, 0, 0, 0, 'Atualmente temos o controle na planilha de calibração do início do uso das soluções de Iodo e Tiossulfato. Porém não temos controle do início de uso das soluções de KI/KIO3 e ácido sulfúrico, que são usadas na checagem  do Titulo.\r\nDevido a falta desse controle tivemos valores do padrão de Iodo fora da especificação, pois faltou a correção das soluções. ', 'Atualizada planilha de calibração conforme foto, para registrar o início do uso de todas as soluções utilizadas no titulador.', 'planilha_de_calibracao.jpg', 'planilha_calibracao_atualizada.jpg', 1095, 1094, 0, 0, 0, 0, '2024-08-12', '2024-08-13', 2, 1082, 2, 2, 3, 2, '', 0, ''),
(1241, 0, 2, 0, 0, 0, 0, 'Foi criado manual de como extrair e organizar todas as requisições de compras abertas no SAP.', 'Maior agilidade no treinamento de novos colaboradores, além de termos uma fonte de pesquisa, para o caso de dúvidas.\r\nArquivo está disponível na pasta \"S:\\CBB\\Geral\\Suprimentos\\Manuais\".', '', 'manual_backlog.jpg', 1164, 1168, 0, 0, 0, 0, '2024-08-13', '2024-10-02', 2, 1, 2, 2, 2, 2, '', 0, ''),
(1242, 0, 4, 0, 0, 0, 0, 'Mudança de procedimento de limpeza dos baldes de óleo e graxa ( descontaminação) para descarte dos mesmos \r\nEm vez de lavar os baldes com Power clean e água, agora dissolvo essa graxa com óleo usado que é para descarte, diminuindo a graxa dos baldes, tornando muito mais fácil a limpeza ', 'Redução em 90% do uso do Power clean \r\nRedução em 60% dos panos para limpeza \r\nZero água e descarte da mesma', 'img_20240813_143414049_hdr.jpg', 'img_20240813_144820987_hdr.jpg', 1097, 0, 0, 0, 0, 0, '2024-08-14', '2024-08-20', 2, 1044, 2, 2, 4, 1, 'Toda matéria prima que for graxa', 0, ''),
