(1294, 0, 2, 0, 0, 0, 0, 'FOI FEITO 2 SUPORTE PARA COLOCAR OS PING.', 'MELHOR PARA TRANPORTA .', '', '', 1037, 1151, 1073, 0, 0, 0, '2024-09-11', '2024-10-02', 2, 1039, 2, 2, 1, 2, '', 0, ''),
(1295, 0, 2, 0, 0, 0, 0, 'Realizado a troca dos frascos da coleta de aditivos do processo, 250ml e 500ml, por frascos de 125ml.', 'A ideia tem como objetivo, evitar o desperdício de aditivos de processo, tais como: carbonato de potássio, lignossulfonato de sódio, amônia.', '', '', 1093, 1094, 0, 0, 0, 0, '2024-09-13', '2024-09-24', 2, 1082, 2, 2, 3, 2, '', 0, ''),
(1296, 0, 1, 0, 13600, 0, 0, 'Temos homologado apenas um fornecedor (Merck) para um reagente utilizado em análise crítica do processo (número de Iodo).', 'Após realização de testes por 3 meses, ficou comprovada a estabilidade do reagente de outro fabricante (Sigma), através do estudo disponível na MOC #4827.', '', 'iodo_sigma.jpg', 1094, 1090, 1164, 0, 0, 0, '2024-09-19', '2024-09-20', 2, 1082, 2, 2, 3, 2, '', 0, ''),
(1297, 0, 1, 0, 570, 0, 0, 'Temos homologado apenas um fornecedor (Brand) para macrocontroladora utilizada na pipetagem durante análise de número de Iodo. ', 'Após 1 mês de testes, foi aprovada nova macro, eliminando a problematica de single source, melhorando custo e sem perder eficiencia na pipetagem.\r\nImportante ressaltar que todos do time colaboraram testando a macro e fornecendo feedback. ', 'macro_brand.jpg', 'macro_vitlab.jpg', 1094, 0, 0, 0, 0, 0, '2024-09-19', '2024-09-20', 2, 1082, 2, 2, 3, 2, '', 0, ''),
(1298, 0, 1, 0, 39680, 0, 0, 'Negociei um frete melhor com a Transjori para os containeres de 40HC que exportamos para a Itália.\r\nA Toniato que seria a primeira opção nos ofertou R$ 5.190,00 por cntr e consegui com a Transjori R$ 3.950,00 por cntr.\r\nNo total transportamos 32 cntrs com a Transjori', 'Conseguimos então uma economia total de R$ 39.680,00 ', '', '', 1051, 0, 0, 0, 0, 0, '2024-09-20', '2024-09-23', 2, 1046, 2, 3, 9, 2, '', 0, ''),
(1299, 0, 1, 0, 2134, 0, 0, 'Negociei um desconto de 7%, com o laboratório responsável por fazer a análise de autoaquecimento no nosso material.\r\nO valor cobrado é por lote e no caso tivemos 5 lotes analisados.\r\nCada laudo era R$3.356,00 X 5 pagaríamos o total de R$ 16.780,00, mas com o desconto de 7% pagamos no final R$ 14.645,94', 'Uma economia total de R$ 2134,06.', '', '', 1051, 1046, 1045, 0, 0, 0, '2024-09-20', '2024-09-23', 2, 1046, 2, 3, 9, 2, '', 0, ''),
(1300, 0, 1, 0, 13113, 0, 0, 'Foi negociado uma redução no spread para as exportações da Itália.\r\nNo geral nos é cobrado 7% para os processos marítimos, mas conseguimos em alguns 4% e em outros 6% .', 'Como resultado economizamos o total de R$ 13.113,63', '', '', 1051, 1042, 0, 0, 0, 0, '2024-09-23', '2024-09-23', 2, 1046, 2, 3, 9, 2, '', 0, ''),
(1301, 0, 4, 0, 0, 0, 0, 'Foi implantado um dispenser para álcool em gel na entrada do Restaurante.', 'Maior higiene ao manter contato com pratos e talheres dispostos no Restaurante.', '', 'alcoolemgel_.jpg', 1164, 1142, 0, 0, 0, 0, '2024-09-25', '2024-10-02', 3, 1, 2, 2, 2, 2, '', 0, ''),
(1302, 0, 4, 0, 0, 0, 0, 'Foi implantado um dispenser para álcool em gel na entrada do Restaurante.', 'Maior higiene ao manter contato com pratos e talheres dispostos no Restaurante.', '', 'alcoolemgel__240925015036.jpg', 1164, 1142, 0, 0, 0, 0, '2024-09-25', '2024-10-02', 2, 1, 2, 2, 2, 2, '', 0, ''),
(1303, 0, 2, 0, 0, 0, 0, 'colocado haste  válvula de agua potável abrandamento. ', 'facilitar abertura da válvula quando necessário alinhar agua potável no abrandor,  uma vez que a mesma se encontra a aproximadamente dois metros de altura.', 'thumbnail_20240919_145614.jpg', 'thumbnail_20240927_030735.jpg', 1075, 1074, 1080, 0, 0, 0, '2024-09-27', '2024-10-02', 2, 1039, 2, 2, 1, 0, '', 0, ''),
(1304, 0, 2, 0, 0, 0, 0, 'colocado engate rápido nas saídas de agua para o abrandado ', 'agilizar a manobra de inversão de agua para o abrandado quando necessário.  ', '', '', 1075, 1074, 1158, 0, 0, 0, '2024-09-27', '2024-10-02', 2, 1039, 2, 2, 1, 0, '', 0, ''),
(1305, 0, 2, 0, 0, 0, 0, 'Foi instalado um suporte para servir de stop para portinhola da válvula de retenção da bomba POS 5191 de emergência contra incêndio, pois a portinhola estava travando no corpo da válvula e dessa forma dando passagem (retornando), ', 'Com o suporte a portinhola fica longe do corpo da válvula assim não tem como travar mais. ', 'antes_240927040724.jpg', 'depois_240927040725.jpg', 1067, 1155, 1152, 0, 0, 0, '2024-09-27', '2024-10-02', 2, 1044, 2, 2, 4, 1, 'Nas demais válvulas que apresentarem o mesmo problema.', 0, ''),
(1306, 0, 2, 0, 0, 0, 0, 'Foi configurado um temporizador no bloco de alarme de falta de energia E_9000.01 ( TRICONEX ) que se alarmado ocorre o shutdown da Planta.', 'Com o temporizador evitaremos o shutdown da Planta por picos de energia fazendo que isso só ocorra quando temos uma queda real de energia.', '', '', 1085, 1071, 0, 0, 0, 0, '2024-09-28', '2024-10-02', 2, 1039, 2, 2, 1, 2, '', 0, ''),
(1307, 0, 2, 0, 0, 0, 0, 'Foi realizado uma melhoria na identificação dos pontos de coleta de agua abrandada e de processo.', 'Facilitar a identificação durante a coleta das amostras, evitando possível erro de identificação  ', '', 'whatsapp_image_2024_10_01_at_16_07_08_1_.jpg', 1081, 1094, 0, 0, 0, 0, '2024-10-01', '2024-10-02', 2, 1039, 2, 2, 1, 2, '', 0, ''),
(1308, 0, 2, 0, 0, 0, 0, 'Aplicação: fluxo de faturamento do granel\r\nMudança\r\n\r\nAntes: Esperávamos o granel pesar para fazer o reporte da ordem no SAP de acordo com o peso balança, só após esse reporte, o lote aparece para a qualidade liberar. Então a qualidade precisa fazer a digitação dos resultados. Enquanto isso, o motorista aguarda a nota.\r\n\r\nAgora: Ao gerar a nota, já é lançado no SAP uma quantidade de 1000kg. Assim o laboratório não precisa mais aguardar o caminhão pesar para visualizar o lote, já pode lançar os valores durante o carregamento, uma vez que a análise é feita até mesmo para liberação do carregamento fisico. Após o caminhão pesar, o responsável pelo faturamento lança somente a diferença de peso que já entrará como liberado no SAP.', 'Redução do tempo de espera de nota fiscal:\r\nOs momentos de demora eram pontuais, então na média de setembro foi uma redução de 10min apenas. 41min para 30min.\r\n\r\nRedução de reclamações:\r\nTivemos no ano, até o mês de agosto um total de 18 reclamações por parte da Bridgestone, por demora na liberação da nota fiscal.', '', '', 1171, 1174, 1094, 0, 0, 0, '2024-10-02', '2024-10-02', 2, 1045, 2, 2, 5, 2, '', 0, ''),
(1309, 0, 2, 0, 0, 0, 0, '\r\nMudança de ponto para abastecimento do tanque do pipa... Que ficava na rua do Silo ou no carbonato. ', 'Com um novo novo ponto... não atrapalha mais o fluxo de veiculo Na rua do Silo ou no carbonato. \r\n\r\nDiminuindo o tempo para encher o tanque de 1:40 hs para 40 min. devido vazão de agua.', '', 'capturar_1.jpg', 1109, 1158, 1152, 0, 0, 0, '2024-10-07', '2024-10-29', 2, 1041, 2, 2, 10, 2, '', 0, ''),
(1310, 0, 2, 0, 0, 0, 0, 'Report do Software Tiamo do Titulador foi editado para melhor e rápida visualização do resultado e adicionado ao layout da tela WORKPLACE onde a análise é feita, para que não seja necessário acessar outra tela para obtenção do valor.', 'Agilidade no processo de coleta de resultado.', 'tiamo_resultado_antes.jpg', 'tiamo_resultado_depois.jpg', 1090, 1096, 1093, 0, 0, 0, '2024-10-08', '2024-10-21', 2, 1082, 2, 2, 3, 2, '', 0, ''),
(1311, 0, 2, 0, 0, 0, 0, 'Feito a criação de um usuário comum - Analista Lab PAA - para o Software Tiamo do Titulador. Antes cada analista tinha um usuário e senha pessoais. Foram mantidos os usuários de administração.', 'Agilidade no uso do Software.', '', '', 1090, 1094, 1095, 0, 0, 0, '2024-10-08', '2024-10-21', 2, 1082, 2, 2, 3, 2, '', 0, ''),
(1312, 0, 2, 0, 0, 0, 0, 'Feito um indicador físico e colocado ao lado dos padrões SRB para indicar o padrão para análise de OAN diário, sem necessidade de preencher a tabela dia a dia com o nome do padrão (devido novo procedimento de checagem diária solicitada).', 'Redução de tempo no preenchimento da tabela mensal; melhoria na visualização da tabela (por conter menos dados) e continuidade no processo de revezamento dos padrões analisados.', 'tabela_de_padroes_antes.jpg', 'tabela_de_padroes_depois.jpg', 1090, 1158, 1082, 0, 0, 0, '2024-10-08', '2024-10-21', 2, 1082, 2, 2, 3, 2, '', 0, ''),
(1313, 0, 2, 0, 0, 0, 0, 'Feito edição na planilha CALIBRAÇÃO para facilitar acesso a edição e coleta de dados sem torná-la vulnerável (acesso era dificultado pois os dados de calibração antes eram lançados no Prguard, e quando foi feito a mudança de plataforma e solicitada a criação da planilha, essa característica foi requerida).', 'Agilidade na coleta e edição de dados por administradores.', '', '', 1090, 1092, 1094, 0, 0, 0, '2024-10-08', '2024-10-21', 2, 1082, 2, 2, 3, 2, '', 0, ''),
(1314, 0, 1, 0, 3876, 0, 0, 'Após a instalação da lança de água antes da Caldeira de Recuperação, reduzimos significativamente o consumo de gás na Caldeira ATA, porém, havia algumas situações onde o operador não se atentava e acabava por permitir a pressão baixar muito.\r\nFoi instalado um temporizador de pulso, quando a pressão abaixa o sistema inicia o pulso programado, até que a pressão se restabeleça.\r\n', 'Estimo que de Janeiro até Outubro, gastamos algo em torno de 1.068Nm3 de gás Natural na Caldeira ATA mesmo com a linha 1 operando', '', '', 1087, 0, 0, 0, 0, 0, '2024-10-16', '2024-10-30', 2, 1039, 2, 2, 1, 0, '', 0, ''),
(1315, 0, 4, 0, 0, 0, 0, 'instalação de tomadas fixa na bancada de serviço de caldeiraria localizado na manutenção', 'tomadas fixas na bancada resulta na rapidez e segurança ao utilizar qualquer ferramenta elétrica (lixadeira, furadeira, retifica) na bancada sem a necessidade de uso de extensões, na qual extensões ficavam espalhadas no chão gerando risco de tropeções do trabalhador ou qualquer outro evento ou curto circuito', 'foto_antes_.jpg', 'foto_depois_.jpg', 1154, 1151, 1071, 0, 0, 0, '2024-10-16', '2024-10-24', 2, 1044, 2, 2, 4, 1, 'locais que tenha bancada fixa com uso continuo de ferramentas eletricas', 0, ''),
(1316, 0, 2, 0, 0, 0, 0, 'Realizado a troca do atuador da válvula de controle 3443.01 do secador linha 3.\r\nproteção no posicionador contra chuva e raio solar.   ', 'Eficiência e agilidade na atuação e evitando falha no posicionador  melhorando no aquecimento da câmera de combustão.', 'fc5de407_02e4_4d2a_964a_74395028e974.jpg', 'f001c6b0_2889_4c4e_abfa_c23b134fb3fc.jpg', 1157, 1154, 1071, 0, 0, 0, '2024-10-17', '2024-10-24', 2, 1044, 2, 2, 4, 1, 'Linha 1,2,3 e utilidades', 0, ''),
(1317, 0, 2, 0, 0, 0, 0, 'Foi elaborado furos na coluna da ensacadeira  hard para realizar a substituição dos rolamentos do carro.', 'Redução de horas trabalhadas e redução de mão de obra, sendo que antes eram necessário dois mecânicos e seis horas trabalhadas. passando para duas horas trabalhada e um mecânico. ', 'coluna_antes_.jpg', 'coluna_depois_.jpg', 1155, 1154, 1158, 0, 0, 0, '2024-10-17', '2024-10-24', 2, 1044, 2, 2, 4, 1, '', 0, ''),
(1318, 0, 4, 0, 0, 0, 0, 'As bombas 2348 e2352 de agua das camisas dos peletizadores estavam com parte dos eixos dos motores expostos.', 'Foi feito uma nova proteção para as partes que estavam expostas evitando risco de acidentes.', '001_241017062412.jpg', '002_241017062414.jpg', 1089, 0, 0, 0, 0, 0, '2024-10-17', '2024-10-30', 2, 1039, 2, 2, 1, 1, '', 0, ''),
(1319, 0, 0, 0, 0, 0, 0, 'Foi elaborado proteção para o PLC garantindo maior vida útil do equipamento.  ', 'Evitando que o PLC  fique exposto a Sol e chuva, e evita toque por acidente na tela.', 'foto_antes__241018035755.jpg', 'foto_depois__241018035755.jpg', 1155, 1071, 1157, 0, 0, 0, '2024-10-18', '2024-10-24', 2, 1044, 2, 2, 4, 1, 'PLC dos Sopradores', 0, ''),
(1320, 0, 3, 0, 0, 0, 0, 'Construída matriz de procedimentos e operadores da expedição e ensaque.\r\n\r\nDevido a última auditoria interna, notamos um ponto de melhoria de que precisávamos ter o registro de treinamentos dos operadores nos procedimentos, porém nem todos deveriam ser treinados em todos, por exemplo, time de empilhadeiristas não necessita treinamento no granel.\r\n\r\nPara facilitar o controle, criei uma planilha parecida com uma RACI com os nomes de procedimentos e quais devem ser aplicados a cada um dos operadores, dessa forma conseguimos revisar mensalmente e verificar quais ainda precisam de treinamentos assim como monitoras os registros.', 'Cobertura do item 7.2 da norma onde diz respeito a gestão de competência.\r\n\r\nFacilidade na visualização de qual treinamento deve ser aplicado a cada operador\r\n\r\nMonitoramento das pendências através de uma rotina de revisão mensal', '', 'matriz_de_procedimentos.jpg', 1171, 0, 0, 0, 0, 0, '2024-10-20', '2024-11-18', 2, 1045, 2, 2, 5, 1, 'Todos os departamentos', 0, ''),
(1321, 0, 2, 0, 0, 0, 0, 'Elaborado em excel uma versão preliminar de uma visão de longo prazo da demanda das ensacadeiras x % de nível dos silos.', 'Consigo visualizar no curto prazo 1 a 2 dias utilizando uma ferramenta que já havia desenvolvido em excel para saber quanto tempo a máquina pode ficar parada, porém, ainda falta ter essa mesma visão de longo prazo.\r\n\r\nNão consigo utilizando a ferramenta anterior, visualizar como vai estar na próxima semana, se vou ter algum espaço disponível para encaixar uma manutenção ou como estarão os níveis, principalmente nos momentos em que estão as 3 linhas rodando.\r\n\r\nCom esse novo gráfico, consigo estimar os níveis e quais graus serão ensacados e em quais turnos, assim consigo prever além dos 2 dias máximos que conseguia anteriormente uma parada da ensacadeira.', '', 'visao_longo_prazo_ensacadeiras.jpg', 1171, 0, 0, 0, 0, 0, '2024-10-20', '2024-11-18', 3, 1045, 0, 2, 5, 2, '', 0, ''),
(1322, 0, 4, 0, 0, 0, 0, 'Controle da talha próximo ao peletizador da linha 02 ficava muito próximo do secador numa área muito quente, já ouve ocasião de danificou o controle e cabos, Foi realocado o suporte do controle para uma área mais longe do secador ', 'Com a realocação do suporte da talha o controle não fico mais exposto a temperatura reduzindo danos ao equipamento', '', '', 1077, 1076, 1158, 0, 0, 0, '2024-10-20', '2024-10-30', 2, 1039, 2, 2, 1, 2, '', 0, ''),
(1323, 0, 2, 0, 0, 0, 0, 'Alterado tipo/tamanho da seta do mouse do SDCD de forma a ficar mais visível', 'A seta ficou maior e da cor preta, bem mais visível', '', '', 1087, 0, 0, 0, 0, 0, '2024-10-21', '2024-10-30', 2, 1039, 2, 2, 1, 0, '', 0, ''),
(1324, 0, 2, 0, 0, 0, 0, 'Foi criada a planilha para controle dos contratos ativos.', 'Maior controle dos contratos no quis respeito a vencimento e a valores mensais dos controle. \r\n\r\nObs.: As informações no arquivo anexo são fictícias.', '', 'controle_de_contratos.jpg', 1164, 1059, 0, 0, 0, 0, '2024-10-21', '2024-12-02', 2, 1178, 2, 2, 2, 2, '', 0, ''),
(1325, 0, 3, 0, 0, 0, 0, 'Durante a realização de análises na capela da sala 05 há um volume considerável de geração de pó. Com  a ligação da luz da capela junto com o funcionamento da exaustão, foi automatizado sistema para funcionamento da capela, tornando esse processo mais eficiente.', 'Com o funcionamento iluminação da capela junto com a exaustão esperamos minimizar o impacto dessa fonte de sujeira na sala 05.', '', '', 1094, 1081, 1157, 0, 0, 0, '2024-10-21', '2024-10-21', 2, 1082, 2, 2, 3, 2, '', 0, ''),
(1326, 0, 4, 0, 0, 0, 0, 'instalado chave fim de curso para acionamento de emergência ensacadeira soft', 'Fim de curso instalado logo apos do sensor superior do elevador da ensacadeira, afim de parar a movimentação do carro se por ventura der falha no sensor de elevação, dando segurança  ao equipamento evitando danos materiais e pessoal\r\nfim de curso instalado junto com o comando de segurança do sistema e botao de reset no painel facilitando o manuseio do operador para correção da falha', 'whatsapp_image_2024_10_21_at_16_38_54_.jpg', 'whatsapp_image_2024_10_21_at_16_40_21_.jpg', 1154, 1071, 1157, 0, 0, 0, '2024-10-21', '2024-10-24', 2, 1044, 2, 2, 4, 1, 'ensacadeira hard nova', 0, ''),
(1327, 0, 2, 0, 0, 0, 0, 'Durante abertura de Concern Reporting na plataforma Gensuite tinhamos que adicionar os nomes dos colaboradores um a um para que todo time tivesse conhecimento e recebesse por email o registro.', 'Foi criado e adicionado um usuário unico para o time LAB PAA facilitando a transmissão da informação.', '', 'gensuite.jpg', 1094, 1082, 1041, 0, 0, 0, '2024-10-22', '2024-10-23', 2, 1082, 2, 2, 3, 1, 'Todos os departamentos que possuem email em grupo.', 0, ''),
(1328, 0, 2, 0, 0, 0, 0, 'Eventualmente realizamos análise do teor de umidade no negro de fumo pelo método via estufa. No procedimento existe a fórmula para calcular o resultado.\r\nFoi criada uma aba em uma planilha já existente no drive interno do laboratório para facilitar o cálculo desse resultado.', 'Agilidade na obtenção do resultado.', 'calculo_manual_atraves_da_formula_no_procedimen.jpg', 'planilha_para_calcular_teor_de_umidade.jpg', 1094, 1082, 0, 0, 0, 0, '2024-10-23', '2024-10-23', 2, 1082, 2, 2, 3, 2, '', 0, ''),
(1329, 0, 2, 200, 0, 0, 0, 'Alguns clientes trabalham com ferramentas digitais para disponibilizar pedidos. Para acessar precisamos do user e senha específicos. Centralizamos essa informação em uma planilha de uso constante das CSs, desta forma todas terão a informação de forma rápida e poderão acessar o portal do cliente caso seja necessário.   ', 'Cada CS tinha a informação de seu cliente, o dado ficou centralizado em um documento de consulta e uso frequente, agilizando o acesso a informação e ao portal dos clientes.  ', '', '', 1048, 0, 0, 0, 0, 0, '2024-10-24', '2024-12-31', 2, 1046, 2, 3, 9, 2, '', 0, ''),
(1330, 0, 2, 0, 0, 0, 0, 'Automatização da válvula de by pass do Secador de Ar Comprimido POS 5358.05', 'Ajudar a evitar parada de produção por falta de Ar Comprimido, decorrente a falha inesperada do equipamento', '', '', 1087, 0, 0, 0, 0, 0, '2024-10-24', '2024-10-31', 3, 1039, 0, 2, 1, 0, '', 0, ''),
(1331, 0, 3, 0, 0, 0, 0, 'montar um supor para mangueira pendurada na válvula', 'Uma melhor visibilidade.', '20241023_112224.jpg', '20241023_154409.jpg', 1162, 1158, 0, 0, 0, 0, '2024-10-25', '2024-10-30', 2, 1039, 2, 2, 1, 2, '', 0, ''),
(1332, 0, 2, 0, 0, 0, 0, 'Instalação de tubings nos mancais superiores da ensacadeira soft para melhorar a lubrificação dos mesmos.', 'Facilitou a lubrificação pois o local é de difícil acesso e tampado por uma proteção.', '', 'cf9afe46_73dc_4f53_98ff_b9299eddec9a.jpg', 1067, 1158, 1097, 0, 0, 0, '2024-10-28', '2024-10-29', 2, 1044, 2, 2, 4, 1, 'Na ensacadeira Hard', 0, ''),
(1333, 0, 2, 8, 0, 0, 0, '  Hoje na entrega da matéria prima ligno sulfonato, é retirada uma amostra para análise, e depois liberar a descarga, junto com a nota fiscal vem uma amostra enviada pelo fornecedor.              \r\n  Foi feito um estudo com vários testes nas amostras Orion e fornecedor, chegando a conclusão que só a amostra do fornecedor é suficiente.\r\n  Este estudo comparativo será compartilhado com os times da produção e lab', 'Não será mais necessário o operador fazer a coleta da amostra, assim vai ganhar tempo e evitar o risco ergonômico pois precisa fazer a coleta embaixo do caminhão.\r\n', '', '', 1096, 1094, 0, 0, 0, 0, '2024-10-29', '2024-11-05', 2, 1082, 2, 2, 3, 0, '', 0, ''),
(1334, 0, 1, 0, 0, 0, 0, 'Na válvula 5358.05, by pass do ar umido com ar seco, se por algum motivo a pressão do ar seco cair abaixo de 5 bar , a válvula abre.', 'Evitar de derrubar as linhas por pressão baixa de ar comprimido.', '', '', 1076, 1077, 1163, 0, 0, 0, '2024-10-30', '2024-10-31', 3, 1039, 0, 2, 1, 0, '', 0, ''),
(1335, 0, 2, 0, 0, 0, 0, 'Mudança no local de acondicionamento dos potes de BBs e reamostras da expedição.\r\nHoje o novo local está situado no armário abaixo do Rotap (equipamento de finos). ', 'Local facilita o manuseio dos potes, limpeza da área, também a organização.', '', '', 1093, 1094, 0, 0, 0, 0, '2024-11-04', '2024-11-07', 2, 1082, 2, 2, 3, 2, '', 0, '');
INSERT INTO `kaizen` (`id_kaizen`, `categoria_kaizen`, `tipo_kaizen`, `tempo_kaizen`, `custo_kaizen`, `reducao_kaizen`, `destaque_kaizen`, `onde_kaizen`, `resultado_kaizen`, `imagem1_kaizen`, `imagem2_kaizen`, `colaborador_kaizen`, `colaborador1_kaizen`, `colaborador2_kaizen`, `colaborador3_kaizen`, `colaborador4_kaizen`, `lider_kaizen`, `datacadastro_kaizen`, `dataconclusao_kaizen`, `status_kaizen`, `admin_kaizen`, `pontos_kaizen`, `unidade_kaizen`, `setor_kaizen`, `outrosdep_kaizen`, `qual_kaizen`, `incidente_kaizen`, `obs_kaizen`) VALUES
(1336, 0, 2, 0, 0, 0, 0, 'Foi instalado novo compressor 5320, e o tube de purga do condensado do ar, ao alinhar a purga movimentava-se o tube.\r\nFeito a fixação do tube para evitar danificar com a movimentação.\r\nNota 000010329486', 'Evitar danos.', '', '', 1084, 1155, 0, 0, 0, 0, '2024-11-04', '2024-12-02', 2, 1039, 2, 2, 1, 2, '', 0, ''),
(1337, 0, 2, 0, 0, 0, 0, '\r\nRemovido a mangueira de vinil que transpassava a tampa e alterado para entrar conduzindo o vinil pelo orifício junto a mangueira de sucção e descarga do abrandador.\r\n\r\nE no orifício da tampa foi instalado conexões com cap, para evitar névoa da solução de salmoura ao agitar.\r\n\r\nUtilizado materiais da bancada da produção.', 'Foi alterado ponto de entrada do vinil no tanque de salmoura, melhorando a dinâmica de adição de NaCl sem esmagar ou danificar a mangueira de vinil que alimenta o \"aerador\".', '', '', 1084, 0, 0, 0, 0, 0, '2024-11-04', '2024-12-02', 2, 1039, 2, 2, 1, 2, '', 0, ''),
(1338, 0, 4, 0, 0, 0, 0, 'Alterado posição do dispositivo de segurança TE2111.10\r\nNota 000010324002', 'Posição antiga do instrumento prejudica a ergonomia do operador durante as trocas de grau na linha 2, podendo colidir com o equipamento devido a proximidade com o porte.', '', '', 1084, 1157, 0, 0, 0, 0, '2024-11-04', '2024-12-02', 2, 1039, 2, 2, 1, 2, '', 0, ''),
(1339, 0, 0, 0, 0, 0, 0, 'Instalado proteção para válvula de pulso da 3 vias de ar da linha 1.\r\nPor o local ser quente e dificultando o acesso para a manutenção  ', 'Melhoria no funcionamento não danificando o monitor e o atuador no dia a dia.', '', '7243dd6b_18ab_484d_8a17_20f61e73c7b6.jpg', 1157, 1120, 1071, 0, 0, 0, '2024-11-06', '2024-11-08', 2, 1044, 2, 2, 4, 1, '3 vias da linha 2 e 3', 0, ''),
(1340, 0, 2, 0, 0, 0, 0, 'Criação de ordens/lote de ensaque de mini bags múltiplos de 19 bags ( capacidade de armazenagem do nível C do rack dinâmico).', 'Melhor organização de armazenagem deixando de ocupar 228 espaços de big bag do armazém.', '', '', 1063, 1171, 1135, 0, 0, 0, '2024-11-07', '2024-11-18', 2, 1045, 2, 2, 5, 2, '', 0, ''),
(1341, 0, 4, 0, 0, 0, 0, 'Durante a análise do teor de cinzas em matéria prima, para acender o bico de meker, e necessário uso de fosforo que por sua vez não é o mais adequado, por isso foi substituído pelo acendedor de maçarico(em estoque no almoxarifado) tornando o processo mais seguro.', 'Ter mais segurança no manuseio do equipamento.', 'thumbnail_img_3175.jpg', '', 1091, 1158, 1094, 0, 0, 0, '2024-11-08', '2024-11-26', 2, 1082, 2, 2, 3, 0, '', 0, ''),
(1342, 0, 4, 0, 0, 0, 0, 'Fixação de novas placas de identificação nos pedestais de isolamento de área para trabalhos em altura e também para trabalhos do mesmo nível.', 'Sinalização dos riscos envolvendo as áreas isoladas para realização das atividades, melhorando a sinalização e identificação dos trabalhos isolados', '', 'placa_de_identificacao_.jpg', 1176, 0, 0, 0, 0, 0, '2024-11-08', '2024-12-02', 2, 1041, 2, 2, 10, 1, 'Em todos os setores que houver necessidade de isolar a área para realização das atividades de risco', 0, ''),
(1343, 0, 2, 0, 0, 0, 0, 'Realizado a manutenção na (PSV) válvula de segurança na linha de agua do grit no laboratório.\r\nO mesmo estava danificado precisando de manutenção a ultima foi em 2013 sabendo que a cadencia é anual.', 'Segurança do equipamento e melhoria no processo.', 'b3cd45a9_c7f1_41af_bd63_2feb0d2d5e46.jpg', '9da1e255_f4c4_4624_9696_ec11245e0f95.jpg', 1157, 1071, 1154, 0, 0, 0, '2024-11-11', '2024-12-02', 2, 1179, 2, 2, 4, 1, 'Peletizadores linha 1 e 3', 0, ''),
(1344, 0, 3, 0, 0, 0, 0, 'Restringir a válvula do tanque 2 de óleo quando estiver descarregado óleo Raro , principalmente da BRASKEM,\r\nQuando não restringe o tanque 2 quando está descarregando a carreta o impacto é direto na qualidade.', 'Verificado que ao restringir na hora da descarga há uma redução desse impacto na qualidade, principalmente L2.', '', '', 1086, 1076, 1077, 0, 0, 0, '2024-12-20', '0000-00-00', 4, 1039, 0, 2, 1, 2, '', 0, 'Olá Marcos. Estou de acordo com esse Kaizen, porém para que seja efetivado seria necessário alguma ação que torne essa atividade rotineira. Exemplo: criar procedimento? \r\nA pergunta é: como podemos tornar essa atividade de forma padrão?'),
(1345, 0, 2, 0, 0, 0, 0, 'Realizado a instalação de válvulas manuais de bloqueio em cada compartimentos da válvulas de exaustão da linha 1. Assim melhorando a troca de atuadores.\r\n', 'Melhor agilidade para fazer uma troca de atuador isolando apenas um compartimento. Antes não tinha como trocar pois o ar comprimido alimentava todas as solenoide dificultando a troca do atuador.', '', '850983db_1955_4288_a305_057fd8741f94.jpg', 1157, 1071, 1154, 0, 0, 0, '2024-11-18', '2024-12-02', 2, 1179, 2, 2, 4, 1, 'filtro primário linha 2', 0, ''),
(1346, 0, 2, 0, 0, 0, 0, 'Hoje o tempo de teste de cinzas feito no RARO é de 16h, porém como não temos nem um tipo de alerta a não ser verbal ou escrita em relatório, costuma se passar um tempo maior dentro da Mufla, tendo assim um consumo de energia desnecessário muito maior que o esperado e também um maior tempo de espera para reportar o resultado.\r\nPara evitar esse tipo de acontecimento está sendo disponibilizado um timer para que tenha um rastreio do teste tanto visual como sonoro', 'Reporte do resultado para a produção em tempo correto e um menor consumo de energia.', 'img_3183.jpg', '', 1091, 1094, 0, 0, 0, 0, '2024-11-26', '2024-12-02', 2, 1082, 2, 2, 3, 0, '', 0, ''),
(1347, 0, 2, 0, 0, 0, 0, 'Hoje o tempo de teste de cinzas feito no RARO é de 16h, porém como não temos nem um tipo de alerta a não ser verbal ou escrita em relatório, costuma se passar um tempo maior dentro da Mufla, tendo assim um consumo de energia desnecessário muito maior que o esperado e também um maior tempo de espera para reportar o resultado.\r\nPara evitar esse tipo de acontecimento está sendo disponibilizado um timer para que tenha um rastreio do teste tanto visual como sonoro', 'Reporte do resultado para a produção em tempo correto e um menor consumo de energia.', 'img_3183_241126044835.jpg', '', 1091, 1094, 0, 0, 0, 0, '2024-11-26', '2024-12-02', 3, 1082, 0, 2, 3, 0, '', 0, ''),
(1348, 0, 2, 0, 0, 0, 0, 'Foi criada uma tabela para controle dos Outline Agreement criados.', 'A planilha possibilita um melhor controle das informações. E, além disso, é possível pesquisar se um determinado código pertence a algum O.A. criado.', '', 'outline_agreement.jpg', 1164, 1168, 0, 0, 0, 0, '2024-11-29', '2024-12-02', 2, 1178, 2, 2, 2, 2, '', 0, ''),
(1349, 0, 4, 0, 0, 0, 0, 'Foi fabricado suporte para carregador de bateria das empilhadeira elétrica da expedição com altura de 50cm do piso.', 'Quando chove no barracão do lona B, fica com muito acumulo de água, com risco de entra água nos carregadores e queima o equipamento, risco grade de curto circuito e também podendo ocasionar choque elétrico.', '', '', 1071, 1151, 1152, 0, 0, 0, '2024-12-03', '2024-12-04', 2, 1179, 2, 2, 4, 2, '', 0, ''),
(1350, 0, 4, 0, 0, 0, 0, 'Criada check-list para pessoa responsável pela limpeza da área.\r\nCheck-list foi criada utilizando o mesmo layout da check-list de empilhadeira e substituindo os itens a serem verificados pelas áreas a serem observadas', 'Com isso conseguimos direcionar melhor o trabalho da pessoa responsável para que entenda e consiga focar nos pontos importantes.\r\nAssim gerando comprometimento e direcionamento.\r\n', '', 'check_list_limpeza.jpg', 1171, 0, 0, 0, 0, 0, '2024-12-03', '2024-12-10', 2, 1045, 2, 2, 5, 1, '', 0, ''),
(1351, 0, 2, 0, 0, 0, 0, 'Realizada parametrização no SAP para geração automática de embarques (VL01) todos os dias durante a troca de turno são gerados os embarques dos dias D+2.', 'Com isso, foi eliminada uma etapa do processo onde deveríamos entrar na ordem através do VA02 e criar um documento de embarque.\r\nBasta só fazer as etapas seguintes do VL02n para selecionar os lotes e transmitir para o coletor.', '', '', 1171, 0, 0, 0, 0, 0, '2024-12-03', '2024-12-10', 2, 1045, 2, 2, 5, 2, '', 0, ''),
(1352, 0, 1, 86, 1349, 0, 0, 'Feito o estudo estatístico do N347 em Produto acabado para redução de custo, onde a análise de OAN será substituída pela análise de Densidade aparente. ', '', '', '', 1091, 0, 0, 0, 0, 0, '2024-12-03', '2024-12-09', 2, 1082, 2, 2, 3, 0, '', 0, ''),
(1353, 0, 2, 0, 0, 0, 0, 'Fazer trend T_211148 (rampa de aquecimento  Reator Soft)\r\n', 'É importante ter o trend para fazer o acompanhamento da rampa de aquecimento do Reator Soft quando faz a partida do mesmo', '', '', 1080, 1075, 1074, 0, 0, 0, '2024-12-04', '2024-12-04', 3, 1039, 0, 2, 1, 1, '', 0, ''),
(1354, 0, 2, 0, 0, 0, 0, 'Fazer trend no instrumento 3121_07 (pressão ar comb)\r\n\r\n\r\n', 'Esse instrumento na instalação do APH novo estava sem trend\r\n\r\n ', '', '', 1080, 1074, 1075, 0, 0, 0, '2024-12-04', '2024-12-23', 2, 1039, 2, 2, 1, 1, '', 0, ''),
(1355, 0, 0, 0, 0, 0, 0, 'Fazer trend do motor peletizador 1310\r\n', 'Na instalação do novo peletizador 1310 não tinha trend de status de ligado.', '', '', 1080, 1075, 1074, 0, 0, 0, '2024-12-04', '2024-12-23', 2, 1039, 2, 2, 1, 1, '', 0, ''),
(1356, 0, 2, 0, 0, 0, 0, 'Fazer trend no instrumento 2352 bomba agua peletização.\r\n', 'Bomba nova de agua de peletização estava sem trend de status de ligada', '', '', 1080, 1075, 1074, 0, 0, 0, '2024-12-04', '2024-12-23', 2, 1039, 2, 2, 1, 1, '', 0, ''),
(1357, 0, 2, 0, 0, 0, 0, 'Aumentar o range da vazão de água peletizador hard e soft \r\n', 'Tem um Intertravamento na vazão de agua dos peletizadores hard e soft, see passa de um valor e fica muito alto por certo tempo desarma a rotativa e para de peletizar esso pode levar até off-spec devido a parada da peletização.\r\nEsse aumento da vazão de agua pode acontecer quando lavamos o peletizador.\r\nA ideia do Kaizem foi aumentar o range do instrumento no campo e fazer a alteração no SDC sendo assim não temos mais esse risco de parar a peletização devido esse intertravamento.', '', '', 1080, 1074, 1075, 0, 0, 0, '2024-12-04', '2024-12-23', 2, 1039, 2, 2, 1, 1, '', 0, ''),
(1358, 0, 2, 0, 0, 0, 0, 'Fazer trend no instrumento 131004 temp. agua quente\r\n', 'Esse intrumento 1310.04 é o retorno de agua quente dos peletizadores hard é importante ter o trend para poder acompanhar a variação da temperatura.', '', '', 1080, 1074, 1075, 0, 0, 0, '2024-12-04', '2024-12-23', 2, 1039, 2, 2, 1, 1, '', 0, ''),
(1359, 0, 2, 0, 0, 0, 0, 'Fazer trend no instrumento 3111_07 \r\n', 'Esse instrumento indica a pressão na saída do ar de processo do APH e não tinha trend para podemos acompanhar. ', '', '', 1080, 1075, 1074, 0, 0, 0, '2024-12-04', '2024-12-23', 2, 1039, 2, 2, 1, 1, '', 0, ''),
(1360, 0, 2, 0, 0, 0, 0, 'Fazer trend no instrumento 1311 ROTATIVA RPM\r\n', 'Rotativa 1311 do peletizador 1310 não tinha trend para verificar a indicação de RPM.', '', '', 1080, 1075, 1074, 0, 0, 0, '2024-12-04', '2024-12-23', 2, 1039, 2, 2, 1, 1, '', 0, ''),
(1361, 0, 2, 200, 0, 0, 0, 'Alteração no RPA para substituir a parametrização dos antigos skus (phase-out) pelos novos (phase-in). \r\n\r\n ', 'O RPA estava parametrizado com os códigos antigos que foram descontinuados, era necessário alterar cada ordem manualmente. Essa alteração elimina o trabalho manual e  agiliza o processo. ', '', '', 1048, 0, 0, 0, 0, 0, '2024-12-04', '2024-12-31', 2, 1046, 2, 3, 9, 2, '', 0, ''),
(1362, 0, 2, 200, 0, 0, 0, 'Centralizar manuais de treinamentos instruções em uma única pasta de acesso. ', 'Os manuais eram enviados via e-mail, com essa alteração eles ficam salvos em um único local facilitando a busca e o acesso para todas as CSs.   ', '', '', 1048, 0, 0, 0, 0, 0, '2024-12-04', '2024-12-31', 2, 1046, 2, 3, 9, 1, 'Todos', 0, ''),
(1363, 0, 4, 0, 0, 0, 0, 'Colocado em uso pinça de madeira para auxiliar na retirada do de tubo de ensaio no teste de Nitrogênio.', 'Segurança para as mãos, evitando possiveis queimaduras', '', 'tubo_de_ensaio.jpg', 1095, 1090, 1093, 0, 0, 0, '2024-12-08', '0000-00-00', 4, 1082, 0, 2, 3, 2, '', 0, 'Silvania,\r\n\r\nPor favor, divulgar o Kaizen para o time através de e-mail ou pelo grupo de whatsapp.\r\nAssim que divulgado, por favor, abrir novamente.'),
(1364, 0, 0, 0, 0, 0, 0, 'Instalado macaquinhos nos mancais do ventilador do ventilador POS1207', 'Melhorou para fazer os ajustes e alinhamento do ventilador.', '', 'd5b493b7_73ee_48ac_8773_2293f28dbacb.jpg', 1067, 1155, 1152, 0, 0, 0, '2024-12-09', '2024-12-11', 2, 1179, 2, 2, 4, 1, 'Nos demais ventiladores', 0, ''),
(1365, 0, 2, 0, 0, 0, 0, 'Instalado porcas tipo borboleta rosca 2581.', 'Facilitar a retirada da tampa em caso de obstrução, ganho de tempo sendo que não e necessário uso de ferramentas .    ', 'thumbnail_screenshot_2024_12_09_13_48_30_704_com_w.jpg', 'thumbnail_screenshot_2024_12_09_13_48_47_797_com_w.jpg', 1075, 1155, 1074, 0, 0, 0, '2024-12-09', '2024-12-23', 2, 1039, 2, 2, 1, 2, '', 0, ''),
(1366, 0, 2, 0, 0, 0, 0, 'Ao marcar férias frequentemente ficamos em dúvida sobre quais regras seguir e acabamos consultando o RH.', 'Foi montado um lembrete e adicionado na planilha de tabela de turno na rede, local onde sempre acessamos para marcar as férias.', '', 'boas_praticas_de_ferias.jpg', 1094, 1082, 1142, 0, 0, 0, '2024-12-09', '2024-12-27', 2, 1082, 2, 2, 3, 1, 'Todas', 0, ''),
(1367, 0, 4, 0, 0, 0, 0, 'Foram anulados 4 furos mais próximos a borda externa do suporte de pipetas, afim de evitar que as pontas das pipetas escorregassem e caíssem na bancada, vindo a trincar a ponta das mesmas.\r\nEsses furos eram os únicos que permitiam o alcance das pipetas para fora do suporte.', 'Redução na quebra da ponta das pipetas por batida contra a bancada, considerando as batidas que ocorriam quando as pipetas estavam no suporte de pipetas.', 'suporte_pipetas_antes.jpg', 'suporte_pipetas_depois.jpg', 1090, 1094, 1093, 0, 0, 0, '2024-12-11', '2024-12-27', 2, 1082, 2, 2, 3, 2, '', 0, ''),
(1368, 0, 1, 0, 2578, 0, 0, 'Foi feito substituição no fabricante da solução tampão de pH usada na checagem do equipamento. Era utilizada solução tampão da Merck, e foi substituída pela solução tampão da Synth. Feito MOC e validada a troca.', 'Redução de custo do reagente: solução tampão Merck 1 litro (custo individual: RS 263,00) / solução tampão Synth 500 ml (custo individual: RS 43,18). Detalhes do cálculo no arquivo em anexo.', '', 'detalhes_reducao_de_custo.jpg', 1090, 1094, 1082, 0, 0, 0, '2024-12-11', '2024-12-27', 2, 1082, 2, 2, 3, 2, '', 0, ''),
(1369, 0, 2, 0, 0, 0, 0, 'Temos um arquivo global para avaliação de projetos de Sustainability no momento do planning anual, onde os valores estão em dólar, as descrições em inglês e o custo das linhas paradas em horas.\r\n Foi automatizado para que a planilha em reais seguindo a cotação do dólar mais recente, os testos foram escritos em português e os custos de linhas paradas convertidos em dias.', 'Assim, ganhamos velocidade e assertividade nas análises dos projetos quanto avaliamos sua priorização no planejamento de CAPEX para o ano seguinte.', 'antes_241211022802.jpg', 'depois_241211022802.jpg', 1068, 0, 0, 0, 0, 0, '2024-12-11', '2024-12-12', 2, 1179, 2, 2, 4, 2, '', 0, ''),
(1370, 0, 4, 0, 0, 0, 0, 'Confeccionar tube de dreno da árvore de vapor L2\r\n Lado direito, após a válvula não há direcionamento do fluído para drenagem na lagoa, pois, quando o sistema está contaminado com óleo e há necessidade de drenar a linha pode ocasionar queimadura no colaborador e sujidade no local.\r\n000060819643\r\n', 'Manutentor \r\nFábio Luca fez parte da execução da atividade.', '', '', 1084, 1158, 0, 0, 0, 0, '2024-12-12', '2024-12-23', 2, 1039, 2, 2, 1, 0, '', 0, ''),
(1371, 0, 4, 0, 0, 0, 0, 'Confeccionado proteção NR12 para a válvula rotativa, no eixo próximo as picagens de ar, no silo off spec 1414 e  2414\r\nNota 000060819378\r\n\r\nMelhoria na segurança do equipamento', '', '', '', 1084, 1155, 0, 0, 0, 0, '2024-12-12', '2024-12-23', 2, 1039, 2, 2, 1, 1, 'Linha 3', 0, ''),
(1372, 0, 4, 0, 0, 0, 0, 'Após o termino da análise de cinzas do RARO é necessário a transferência dos cadinhos para o dessecador, para melhorar a segurança e a movimentação dentro do laboratório, foi disponibilizado uma bandeja resistente ao calor com a capacidade para 8 cadinhos.', 'Transferir e movimentar os cadinhos dentro do laboratório com mais segurança.', '', 'bandeja.jpg', 1091, 1094, 0, 0, 0, 0, '2024-12-12', '2024-12-27', 2, 1082, 2, 2, 3, 0, '', 0, ''),
(1373, 0, 4, 0, 0, 0, 0, 'Fabricado um contentor com rodinha para o equipamento NDM do laboratório.\r\nServiço realizado por: Carlos Cesar e  Adriano reis na montagem\r\nServiço realizado por: Tarcísio lima e Antônio neles na instalação', 'Melhoria e deslocamento do equipamento para limpeza e se houver algum vazamento  o contentor armazena a água tendo um dreno para dispensar para a canaleta.  ', '0ad986b1_a005_4b64_8d9d_a5757814fc94.jpg', '5afd7f80_9381_4e5d_a051_996811ebdd02.jpg', 1157, 1151, 1152, 0, 0, 0, '2024-12-12', '2024-12-16', 2, 1179, 2, 2, 4, 1, 'Motor da prensa', 0, ''),
(1374, 0, 2, 0, 0, 0, 0, 'Foi identificado para os carregamentos da Bridgestone de Tot Bin a quantidade de bins a serem carregados até a tampa para o peso seguir conforme o cliente deseja.\r\nNo carregamento de N330 foi identificado que precisamos carregar todos os 22 bins até a tampa para o peso ficar entre 16.000 kg até 17.000 kg, peso esse solicitado pelo cliente;\r\nNo carregamento de N326 foi identificado que precisamos carregar somente 16 bins até a tampa para o peso ficar entre 16.000 kg até 17.000 kg, peso esse solicitado pelo cliente;\r\n', 'Desta forma o operador de envase de granel, ganhou mais agilidade no carregamento e sabe a quantidade de bins para carregar por material para o peso ficar como o solicitado pelo cliente.\r\nEliminado a questão do peso ficar menor e o veículo precisar entrar novamente para carregamento, ou o peso ficar maior e não termos condições de descarregar.\r\n', '', '', 1064, 1171, 1172, 0, 0, 0, '2024-12-15', '2024-12-17', 2, 1045, 2, 2, 5, 2, '', 0, ''),
(1375, 0, 4, 0, 0, 0, 0, 'Demarcar no estacionamento da portaria uma vaga para idoso e outra vaga para PcD.', 'Garantir vaga para pessoas com melhor idade e PcD.', '', '', 1041, 1176, 0, 0, 0, 0, '2024-12-16', '2024-12-26', 2, 1036, 2, 2, 10, 1, 'manutenção', 0, ''),
(1376, 0, 2, 0, 0, 0, 0, 'A alimentação de água para o sistema de abrandamento antes, para mudar de agua potável para de água de processo, era necessário soltar a flange de um ponto e parafusar em outro.', 'Foi colocado um sistema de engate rápido para facilitar a manobra quando necessário fazer a troca.', '', 'thumbnail_img_8539.jpg', 1089, 0, 0, 0, 0, 0, '2024-12-17', '2024-12-23', 2, 1039, 2, 2, 1, 0, '', 0, ''),
(1377, 0, 2, 10, 0, 0, 0, 'Melhoria no processo de importação de informações na folha de pagamento por meio de planilha evitando lançamentos manuais.', 'Obtenção de autonomia e agilidade nos processos de alterações de valores para a folha de pagamento.', '', '', 1177, 1142, 1047, 0, 0, 0, '2024-12-17', '2025-01-03', 2, 1043, 2, 2, 8, 2, '', 0, ''),
(1378, 0, 2, 7, 0, 0, 0, 'Criação de código de benefício para previdência privada contribuição voluntária para refletir na folha de pagamento automaticamente.', 'Evita o processo de lançamentos manuais e automatização das atualizações das contribuições.', '', '', 1177, 1142, 1047, 0, 0, 0, '2024-12-17', '2025-01-03', 2, 1043, 2, 2, 8, 2, '', 0, ''),
(1379, 0, 2, 24, 0, 0, 0, 'Melhoria no processo de rateio dos benefícios: transporte coletivo e refeitório, para a folha de pagamento.', 'Substituição dos lançamentos manuais por abertura de chamado ou importação em sistema via planilha eletrônica. Obtendo mais agilidade no processo.', '', '', 1177, 1142, 1047, 0, 0, 0, '2024-12-17', '2025-01-03', 2, 1043, 2, 2, 8, 2, '', 0, ''),
(1380, 0, 2, 0, 0, 0, 0, 'Feito a instalação do medidor de vazão do óleo no by-pass aonde já fica o medidor de vazão existente FT.2111.11 da linha 2\r\nMontagem e instalação: Tarcísio lima e Carlos Cesar', 'Agilidade na troca, ganho no tempo  e sem risco de vazamento, ou queda da linha aproveitando a mesma ligação de cabos elétricos e de instrumentação. \r\nVerificação em campo: Rogerio e Sebastião', 'babe724f_f2ac_4384_bee1_6d8044b533b3.jpg', '44317e33_8ba4_4af0_bc63_2080b5d76a51.jpg', 1157, 1158, 1152, 0, 0, 0, '2024-12-17', '2025-01-03', 2, 1179, 2, 2, 4, 1, 'Linhas 1 e 3     FT.1111.11 e FT.3111.11', 0, ''),
(1381, 0, 2, 18, 0, 0, 0, 'Foi desenvolvida uma planilha de excel, que através de fórmulas que buscam informações de uma relatório padrão extraído do SAP, consolidam as informações de notas fiscais lançadas em determinadas contas contábeis e centros de custos.', 'Através dessas informações consolidadas, reduzi o tempo de análise das notas fiscais lançadas em cada centro de custo. Esse relatório consolida as informações de uma forma que posso identificar com mais facilidade se uma nota fiscal de recorrência mensal foi lançada ou não. Com isso, tenho tempo hábil para entrar em contato com o responsável a fim de evitar dispersão no budget ou justificar variações de uma forma mais detalhada.', '', 'imagem5.jpg', 1141, 0, 0, 0, 0, 0, '2024-12-18', '2025-06-18', 2, 1040, 2, 2, 6, 2, '', 0, ''),
(1382, 0, 2, 0, 0, 0, 0, 'Feito substituição do gelo comum (feito em fôrmas com água) por gelo reutilizável.', 'Praticidade e economia de tempo na execução da análise.', 'gelo_tradicional.jpg', 'gelo_reutilizavel.jpg', 1090, 1094, 1096, 0, 0, 0, '2024-12-18', '2024-12-27', 2, 1082, 2, 2, 3, 2, '', 0, ''),
(1383, 0, 4, 0, 0, 0, 0, 'Foi instalado um suporte de parede para caixas de luvas, ao lado da mesa dos analistas.', 'Organização do ambiente de trabalho, apoio para retirada de luvas da caixa, padronização do ambiente para facilitação na execução de tarefas do dia a dia.', 'caixa_de_luvas_antes.jpg', 'caixa_de_luvas_depois.jpg', 1090, 1091, 1095, 0, 0, 0, '2024-12-19', '2024-12-27', 2, 1082, 2, 2, 3, 1, 'Cozinha / Pia externa da sala de controle / entrada da logística', 0, ''),
(1384, 0, 3, 0, 0, 0, 0, 'O detector de movimento dos secadores  estavam  atuando com frequência ocasionando a queda dos mesmos  foi verificado que é apenas sujeira sobre o sensor , foi sugerido a configuração  da redundância destes sensores pois existem 2 em cada secador.', 'Foi implementado o sistema de detector com alarme redundante, com funcionalidade adequada. ', '', '', 1086, 1163, 1076, 0, 0, 0, '2024-12-20', '2024-12-23', 2, 1039, 2, 2, 1, 2, '', 0, ''),
(1385, 0, 0, 0, 0, 0, 0, 'Soprador 3122 não trabalha em automático quando está individualmente, a sugestão é que seja configurado para trabalhar em auto quando estiver trabalhando individualmente economizando energia.', 'Foi implementado ,o que facilitou o trabalho em caso de intercalar o soprador 3 com o soprador 1 ou 2. ', '', '', 1086, 1163, 1077, 0, 0, 0, '2024-12-20', '2024-12-23', 2, 1039, 2, 2, 1, 2, '', 0, ''),
(1386, 0, 1, 0, 0, 0, 0, 'A Linha 2 na produção  da maioria dos grades há a possibilidade de ajuste na redução  da CP% em pelo menos 1% para um rendimento maior nos grades soft, Podendo  iniciar com o N683  ', 'Já algum tempo não fez este ajuste , podendo ai uma oportunidade de rendimento.', '', '', 1086, 1163, 1076, 0, 0, 0, '2024-12-20', '2025-01-03', 3, 1039, 0, 2, 1, 2, '', 0, ''),
(1387, 0, 2, 48, 0, 0, 0, 'Tratado com a logística e implementado para o CD Guarulhos, que não praticava esta rotina , a antecipação dos processos de separação para 1 dia útil antes da data de carregamento.', 'Maior agilidade nos processos para os casos que necessitavam de ajustes , de liberação de materiais bloqueado e de entrada fiscal . Evitando assim atrasos em entregas. ', '', '', 1046, 1064, 0, 0, 0, 0, '2024-12-20', '2025-01-06', 2, 1038, 2, 3, 9, 0, '', 0, ''),
(1388, 0, 0, 0, 5858, 0, 0, 'Solicitação e indicação para logística reduzir o número de lotes para a exportação que necessita de teste de auto aquecimento.', 'Em um dos processos ao invés de trabalhar a documentação com 3 lotes trabalhamos com 1 . Tendo o custo para apenas para 1 lote , pois a cobrança é por por lote. ', '', '', 1046, 1063, 1045, 0, 0, 0, '2024-12-20', '2025-01-06', 2, 1038, 2, 3, 9, 0, '', 0, ''),
(1389, 0, 2, 108, 0, 0, 0, 'Planilha de acompanhamento de informações para exportação, cliente Goodyear - Chile.\r\nUnificação de todas as informações .Facilitando a comunicação e troca de informações que deverão ser compartilhadas entre logística , faturamento , CS , Servimex , transportadora e cliente.  ', 'Agilidade no processo, melhora na localização da informações , melhor rastreabilidade.  ', '', '', 1046, 1064, 0, 0, 0, 0, '2024-12-20', '2025-01-06', 2, 1038, 2, 3, 9, 1, '', 0, ''),
(1390, 0, 2, 0, 0, 0, 0, 'Criação da Biblioteca de fluxo de trabalho. Usada para auxiliar na execução de transações detalhadamente.     ', 'otimização em fluxos de trabalho em tempo , auxilio e melhora na comunicação.  ', '', '', 1046, 1048, 1172, 0, 0, 0, '2024-12-20', '2025-01-06', 2, 1038, 2, 3, 9, 1, '', 0, ''),
(1391, 0, 2, 36, 0, 0, 0, 'Criação de alerta para comunicação nas alterações realizadas na Análise Crítica de Clientes. Em andamento, teste já realizados.  ', 'Melhora na comunicação.\r\nImplementado uma comunicação automática, após as alterações realizadas. ', '', '', 1046, 1092, 0, 0, 0, 0, '2024-12-20', '2025-01-06', 2, 1038, 2, 3, 9, 0, '', 0, ''),
(1392, 0, 2, 0, 0, 0, 0, 'Criação do checking list de exportação para CS. \r\nRelacionando todas as atividades, fornecedores das informações, indicando prazos e complexidade de cada etapa. ', 'Garantia de que todas as fases sejam executadas com maior agilidade e eficácia.  ', '', '', 1046, 0, 0, 0, 0, 0, '2024-12-20', '2025-01-06', 2, 1038, 2, 3, 9, 2, '', 0, ''),
(1393, 0, 4, 0, 0, 0, 0, 'Reorganização das ordens, check-lists de verificação de embalagens e descarte das ordens antigas.\r\n\r\nForam descartadas as ordens com mais de 1 ano de arquivo, liberado espaço para movimentar as check-lists e movimentada para a gaveta de baixo.\r\n\r\nTambém foram identificadas as gavetas com o que há e reduzido a quantidade de documentos.', 'Devido a gaveta estar cheia, quando abria-se a gaveta ela começava a cair e tinha que segurar.\r\n\r\nComo o volume de controle das check-lists aumentou devido a quebra de lotes da aceflex e lotes pequenos da sanwey, facilitou o acesso com essa reorganização.', '20241220_171038.jpg', '20241220_171541.jpg', 1171, 1055, 1170, 0, 0, 0, '2024-12-20', '2024-12-23', 2, 1045, 2, 2, 5, 1, 'Onde existem armários não identificados', 0, ''),
(1394, 0, 4, 0, 0, 0, 0, 'Colocado em uso pinça de madeira para auxiliar na retirada do tubo de ensaio quente, do aparelho no teste de Nitrogênio.', 'Segurança para as mãos, evitando queimaduras.\r\nOs analistas  foram orientados em como usar a pinça, também foi enviado email e mensagens no whatssap.', '', 'tubo_de_ensaio_241222112138.jpg', 1095, 1090, 1093, 0, 0, 0, '2024-12-22', '2024-12-27', 2, 1082, 2, 2, 3, 2, '', 0, ''),
(1395, 0, 3, 0, 0, 0, 0, 'Melhorias no relatório de turno do laboratório', 'Com essas modificaçoes no relatório de turno  foi obtida uma melhora na comunicação entre os analistas', 'relatorio_de_turno_antes.jpg', 'relatorio_de_turno_depois.jpg', 1095, 1092, 1082, 0, 0, 0, '2024-12-23', '2024-12-27', 2, 1082, 2, 2, 3, 2, '', 0, ''),
(1396, 0, 1, 0, 657, 0, 0, 'Foi feito substituição da concentração da solução de Tiossulfato de sódio utilizado na análise de Número de Iodo. Antes era usado Tiossulfato de sódio 0,05N, e agora será usado Tiossulfato de sódio 0,0394N.\r\nA redução de custo está no reagente Iodato de potássio, usado no preparo da solução padrão primário Iodeto Iodato de potássio, que por sua vez é utilizada na padronização da solução Tiossulfato de sódio.', 'Redução de custo no reagente Iodato de potássio, e consequente alinhamento com outras plantas Orion que utilizam a concentração 0,0394N para o Tiossulfato de sódio.', '', 'reducao_custo_iodeto_de_potassio.jpg', 1090, 1092, 1082, 0, 0, 0, '2024-12-23', '2024-12-27', 2, 1082, 2, 2, 3, 2, '', 0, ''),
(1397, 0, 2, 0, 0, 0, 0, 'Feito vídeo demonstrativo do procedimento de limpeza do header de óleo com vapor após parada de linha.', 'Com o procedimento em vídeo fica muito mais fácil o entendimento da manobra e também reduz possibilidade de erros.', '', '', 1089, 0, 0, 0, 0, 0, '2024-12-23', '2024-12-23', 2, 1039, 2, 2, 1, 1, 'Pode ser feito vídeos explicativos de outros processos que exigem mais atenção na execução.', 0, ''),
(1398, 0, 2, 0, 0, 0, 0, 'Durante uma análise dos cálculos de previsão consumo de gás natural x consumido real, foi percebido uma tendência de erro de programação quando a L1 está parada.\r\nNa fórmula de cálculo de previsão do consumo foi adicionado uma condicional para somar uma valor referente a caldeira para as situações em que a L1 está parada.', 'Melhor assertividade e acuracidade no erro de programação de gás natural.', '', 'imagem_formula_final.jpg', 1045, 0, 0, 0, 0, 0, '2024-12-23', '2024-12-26', 2, 1036, 2, 2, 5, 2, '', 0, ''),
(1399, 0, 0, 0, 0, 0, 0, '', '', '', '', 1045, 0, 0, 0, 0, 0, '2024-12-23', '2024-12-26', 3, 1036, 0, 2, 5, 0, '', 0, ''),
(1400, 0, 2, 300, 0, 0, 0, 'Eliminar o envio automático de confirmação de pedidos de grandes programações. Esses e-mails são enviados e não tem nenhuma funcionalidade, e também gera  retrabalho pois temos que excluir um por um, ainda correndo o risco de eliminar algum e-mail importante. ', 'Otimização de tempo eliminando retrabalho desnecessário, liberando mais tempo para atividades importantes e eliminando o risco de excluir mensagens necessárias.', '', '', 1048, 0, 0, 0, 0, 0, '2024-12-23', '0000-00-00', 4, 1050, 0, 3, 9, 2, '', 0, 'Olá,\r\nPor favor, precisamos detalhar melhor o que é este envio automático, como funciona e porque temos que excluí-los.\r\nTambém detalhar como chegamos nestas 300 horas por ano.\r\nOutro ponto importante, se a ação já foi implementada.\r\n\r\nObrigado!\r\nJoão'),
(1401, 0, 2, 0, 0, 0, 0, 'Realizar furos na caixa de engrenagem de corrente da Ensacadeira Hard, devido muito acúmulo de material dentro da mesmo, podendo danificar o equipamento', '', '', '', 1055, 0, 0, 0, 0, 0, '2024-12-24', '2025-01-03', 2, 1045, 2, 2, 13, 2, '', 0, ''),
(1402, 0, 4, 0, 0, 0, 0, 'Foi colocado um bandeja em baixo da saboneteira, evitando cair gotas de sabão no chão.', 'Com a proteção da bandeja, não ocorrerá mais pingos no chão evitando possíveis escorregôes.', 'pingo_.jpg', 'bandeja_.jpg', 1095, 1094, 1090, 0, 0, 0, '2024-12-24', '2024-12-27', 2, 1082, 2, 2, 3, 2, '', 0, ''),
(1403, 0, 2, 30, 0, 0, 0, 'Planilha de Programação de Pedido Mensal criada para o cliente Maggion com a programação mensal de acordo com a solicitação por item enviada pelo cliente por e-mail, para utilização da ferramenta de automação de pedidos em vigor, RPA. Como o cliente não emite pedido mensal, e somente envia a solicitação mensal de pedidos por e-mail, foi criada essa planilha.', 'Com essa planilha temos todas as informações necessárias para envio da programação à ferramenta RPA de automação de pedidos que está em vigor, o que nos permite otimizar o tempo de trabalho, ter acuracidade nas informações fornecidas, e mais agilidade no processo possibilitando termos a programação completa no sistema em menor tempo.', '', 'kaizen_maggion_modelo_planilha.jpg', 1172, 0, 0, 0, 0, 0, '2024-12-26', '2024-12-31', 2, 1046, 2, 3, 9, 2, '', 0, ''),
(1404, 0, 2, 48, 0, 0, 0, 'Planilha de Programação de Pedido Mensal criada para o cliente Anastácio com a programação mensal de acordo com a solicitação por item enviada pelo cliente por e-mail, para utilização da ferramenta de automação de pedidos em vigor, RPA. Como o cliente não emite pedido mensal, e somente envia a solicitação mensal de pedidos por e-mail, foi criada essa planilha.\r\n', 'Com essa planilha temos todas as informações necessárias para envio da programação à ferramenta RPA de automação de pedidos que está em vigor, o que nos permite otimizar o tempo de trabalho, ter acuracidade nas informações fornecidas, e mais agilidade no processo possibilitando termos a programação completa no sistema em menor tempo.', '', 'kaizen_anastacio_modelo_planilha.jpg', 1172, 0, 0, 0, 0, 0, '2024-12-26', '2024-12-31', 2, 1046, 2, 3, 9, 2, '', 0, ''),
(1405, 0, 2, 0, 0, 0, 0, 'Foi retirado o preenchimento de checklist de descarregamento de matéria prima em papel, todo recebimento era necessário realizar o checklist em papel, \r\n\r\n', 'Foi transferido o checklist de papel para arquivo eletrônico, o documento continua sendo preenchido mas  de forma eletrônica \r\n\r\nEm  2024 foi economizadas 1012 folhas de papel ', '', '', 1081, 1092, 0, 0, 0, 0, '2024-12-26', '2025-01-03', 2, 1039, 2, 2, 1, 0, '', 0, ''),
(1406, 0, 2, 7, 0, 0, 0, 'Modificado instrução de entrega da empresa Xpert Pack (Aceflex) para que os bags venham empilhados em 2 de altura (Chão + 1)\r\nAlterações foram realizadas pela Xpert na FTec (Ficha Técnica) que demonstram as instruções necessárias para os bags da Orion.', 'No ano de 2024 recebemos 20 entregas da Aceflex, considerando que todas foram no lastro, reduzimos 10 entregas e ocupação da operação.\r\nCom a oportunidade de aumento do crescimento da Aceflex, temos também a oportunidade de redução de custo pela parte de suprimentos que ainda não foi finalizada.', '', 'instrucao_tecnica_aceflex.jpg', 1171, 1164, 0, 0, 0, 0, '2024-12-27', '2025-01-03', 2, 1045, 2, 2, 5, 2, '', 0, ''),
(1407, 0, 2, 24, 0, 0, 0, 'Envio de comunicação diária para Goodyear-Americana indicando local de coleta ( Paulínia e MBM ) e com a informação de transportadora atrelada. Este processo foi implementado para auxiliar a Goodyear em suas retiras.  ', 'Economia de tempo em caso de alterações, avaliação previa por parte da Goodyear em caso de troca de transportadora e redução  no fluxo de trabalho de nossa logística.', '', '', 1046, 1064, 0, 0, 0, 0, '2024-12-27', '2025-01-06', 2, 1038, 2, 3, 9, 0, '', 0, ''),
(1408, 0, 2, 48, 0, 0, 0, 'Cronograma de acompanhamento das validades e fluxo de renovações de cada  declaração de exportação que é feita.', 'Antecipação e melhoria no acompanhamento de cada processo, visando agilidade para emissão do COO. ', '', '', 1046, 0, 0, 0, 0, 0, '2024-12-27', '2025-01-06', 2, 1038, 2, 3, 9, 0, '', 0, ''),
(1409, 0, 1, 0, 636, 0, 0, '1. Foi calculado o custo por análise de Transmitância (reagente e material).\r\n2. Foi definida a proposta de redução que constará na Folha de marcha: Linhas 1 e 3: teste 2 x por corrida / HS25 e HS45: teste na amostra completa / após isso-dia sim, dia não.\r\n3. Foi calculado o custo total das análises em amostra de secador da produção do ano de 2023 (para as Linhas 1 e 3, e para HS25 e HS45) - dados do SAP.\r\n4. Foi calculada a redução de número de análises conforme a quantidade de Ordens de Processo do ano de 2023.\r\n5. Foi calculada a redução de custo anual utilizando números do ano de 2023 (custo por análise / número de testes realizados em 2023 / quantidade de Ordens de Processo / número de testes reduzidos na Folha de marcha).\r\n6. Foi obtido através desse cálculo a % de redução de custo do ano de 2023.\r\n7. Foi calculado o custo da análise por tonelada de produção do ano de 2023 (para as Linhas 1 e 3, e para HS25 e HS45).\r\n* Ponderação para o cálculo de Saving:\r\nConsiderando a menor % de redução de custo nas análises de Transmitância em amostra de secador - 48%: \r\nFoi calculada a redução de custo para 2025 utilizando o valor da análise por tonelada de produção, utilizando a estimativa de produção para o ano (ver tabela em anexo).\r\n\r\n\r\n\r\n', 'Redução de custo e melhoria no fluxo de trabalho do CQ.', '', 'calculo_reducao_custo_transmitancia.jpg', 1090, 1082, 1093, 0, 0, 0, '2024-12-30', '2025-01-02', 2, 1082, 2, 2, 3, 2, '', 0, ''),
(1410, 0, 3, 0, 0, 0, 0, 'Lança central do reator 1, na parada foi ajustado o zero na lança central no choke, foi realizado uma marca na lança e para as próximas uma regua vai ser desenvolvida.', 'Ter a certeza que a lança central vai estar realmente no centro do choke.', '', '', 1076, 1158, 1077, 0, 0, 0, '2025-01-01', '2025-01-03', 2, 1039, 2, 2, 1, 1, 'Reator 3', 0, ''),
(1411, 0, 3, 0, 0, 0, 0, 'No reator 3 existia um dreno na tubulação de carbonato do lado esquerdo do reator que não estava sendo usado, foi retirado o dreno e instalado um cap.', 'Evitar que alguém sem querer encoste no dreno, pois isso causaria transtorno na qualidade do produto, tendo em vista que o carbonato controla o OAN.', '', '', 1076, 1077, 1086, 0, 0, 0, '2025-01-01', '2025-01-03', 2, 1039, 2, 2, 1, 2, '', 0, ''),
(1412, 0, 2, 0, 0, 0, 0, 'Inserir lança de gás normal o invés da startup no reator 2, na rampa de aquecimento.', 'Melhor controle na rampa inicial, pois a lança normal da menos vazão que a startup.', '', '', 1076, 1077, 1086, 0, 0, 0, '2025-01-01', '0000-00-00', 4, 1039, 0, 2, 1, 0, '', 0, ''),
(1413, 0, 2, 0, 0, 0, 0, 'Com intuito em reduzir alarmes sonoros sem necessidade de ação imediata, foi calado todos alarmes sonoros vindos dos Abrandados, visto que o PLC é autônomo. ', '', '', '', 1087, 0, 0, 0, 0, 0, '2025-01-05', '2025-02-18', 2, 1039, 2, 2, 1, 0, '', 0, ''),
(1414, 0, 2, 0, 0, 0, 0, 'Realizado a substituição do atuador da válvula de ar de aquecimento da câmera de combustão do secador linha 2 \r\nObs: Atuador que estava existente estava com vazamento de ar nas conexões não tem força para modular de 0 a 100% de abertura. ', 'Eficiência e melhoria na atuação dando  melhor rendimento de ar para a câmera de combustão  processo. ', '4bd2e7de_b07a_4c06_9615_a00f9feed7ad.jpg', '09f74771_158c_4c2a_a14b_e0e194478c65.jpg', 1157, 1071, 1158, 0, 0, 0, '2025-01-10', '2025-01-15', 2, 1179, 2, 2, 4, 1, 'Linha 1,2,3', 0, ''),
(1415, 0, 2, 0, 0, 0, 0, 'Realizado a troca do medidor de vazão de amônia para atender as necessidade do secador 1 nas medição da Cetesb.', 'Melhoria na qualidade e no processo valor bem estável sem oscilação de vazão ', '30f7c45c_8d64_4d3f_aaec_10f4a875d3d5.jpg', 'e67c5073_9833_498b_a4a1_2ca7f6be9626.jpg', 1157, 1071, 1154, 0, 0, 0, '2025-01-10', '2025-01-15', 2, 1179, 2, 2, 4, 1, 'Linha 1,2,3', 0, ''),
(1416, 0, 2, 0, 0, 0, 0, 'Foi instalado uma valvula na linha de vapor nos filtro primário da linha 1 e 2 próximo ao ponto de amostragem ', 'Lá existe um duplo bloqueio porém uma das válvulas ficava numa altura elevada oque dificultava o alinhamento, com a instalação da valvula mais próxima uma da outra não foi mais preciso de andaime oque diminui o risco de acidente e custo além de facilitar as manobras da área ', '', '', 1077, 1151, 1076, 0, 0, 0, '2025-01-11', '2025-02-18', 2, 1039, 2, 2, 1, 0, '', 0, ''),
(1417, 0, 2, 0, 0, 0, 0, 'Instalado um suporte para mangueira de vapor próximo as bombas de óleo', 'Mangueira de vapor ficava antes enrolada no tanque pulmão de vapor que com a temperatura poderia danificar a mangueira, com a instalação do suporte conseguimos organizar melhor a mangueira e evitando possível danos ', '', '', 1077, 1151, 1076, 0, 0, 0, '2025-01-11', '2025-02-18', 2, 1039, 2, 2, 1, 2, '', 0, ''),
(1418, 0, 4, 0, 0, 0, 0, 'Padronização nas etiquetas de identificação das almotolias de óleo usada na lubrificação ', 'Qualidade na visualização e identificação das almotolias,e menos risco de erro na escolha de em emergência, alguém pegar uma almotolia errada ', '', 'img_20250114_144243113_mfnr.jpg', 1097, 0, 0, 0, 0, 0, '2025-01-14', '2025-01-15', 2, 1179, 2, 2, 4, 1, 'Todos os recipiente usado na lubrificação que precisa de identificação', 0, ''),
(1419, 0, 4, 0, 0, 0, 0, 'Padronização nas etiquetas de identificação das almotolias de óleo usada na lubrificação ', 'Qualidade na visualização e identificação das almotolias,e menos risco de erro na escolha de em emergência, alguém pegar uma almotolia errada ', '', 'img_20250114_144243113_mfnr_250114025120.jpg', 1097, 0, 0, 0, 0, 0, '2025-01-14', '2025-01-15', 3, 1179, 0, 2, 4, 1, 'Todos os recipiente usado na lubrificação que precisa de identificação', 0, ''),
(1420, 0, 2, 0, 0, 0, 0, 'REALIZADO A INDENTIFICAÇÃO DE ETIQUETAS PARA CAIXA \r\nPARA COLOCAR OS CHECKLIST DE EMBALAGENS AGUARDANDO INSPEÇÃO / E ETIQUETAS COM EMBALAGEM JA INSPECIONADA', '', '', 'foto_inspecao_.jpg', 1055, 0, 0, 0, 0, 0, '2025-01-14', '2025-01-15', 2, 1045, 2, 2, 13, 2, '', 0, ''),
(1421, 0, 2, 0, 0, 0, 0, 'Automação de impressão das folhas de check list de transferencia com recurso de mala direta do word junto com uma planilha para automatizar o fluxo', 'Otimização do preenchimento manual reduzindo tempo de preenchimento da folha.', '', '', 1063, 1182, 0, 0, 0, 0, '2025-01-16', '2025-01-16', 2, 1045, 2, 2, 5, 2, '', 0, ''),
(1422, 0, 3, 0, 0, 0, 0, 'Criado pasta para armazenagem dos relatórios de fumigação recebido com os pallets. Não temos local definido para eles. Foi identificada uma pasta no arquivo para essa finalidade.', 'Historico de relatorios caso haja necessidade de rastreabilidade de lotes recebidos do fornecedor de pallet', '', '', 1063, 0, 0, 0, 0, 0, '2025-01-16', '2025-01-16', 2, 1045, 2, 2, 5, 2, '', 0, ''),
(1423, 0, 3, 0, 0, 0, 0, 'Sugestão de inclusão de sequencia de lote para lotes de bags recebidos do fornecedor Bonsucesso ( fornecedor enviava com um unico lote para todo volume de fabricacao de big bag anual). Foi sugerido incluir um numero sequencial por entrega para acompanhamentos e rastreabilidade correta', 'Rastreabilidade big bags em caso de alguma não conformidade.', '', '', 1063, 0, 0, 0, 0, 0, '2025-01-16', '2025-01-16', 3, 1045, 0, 2, 5, 0, '', 0, ''),
(1424, 0, 0, 0, 0, 0, 0, '\r\n\r\nSugestão de inclusão de sequencia de lote para lotes de bags recebidos do fornecedor Bonsucesso ( fornecedor enviava com um unico lote para todo volume de fabricacao de big bag anual). Foi sugerido incluir um numero sequencial por entrega para acompanhamentos e rastreabilidade correta\r\n\r\n\r\n\r\n\r\n', '\r\nRastreabilidade big bags em caso de alguma não conformidade.', 'bonsucesso.jpg', '', 1063, 0, 0, 0, 0, 0, '2025-01-16', '2025-01-16', 2, 1045, 2, 2, 5, 2, '', 0, ''),
(1425, 0, 2, 0, 0, 0, 0, 'Instalado purgador no filtro de ar comprimido do secador de sílicas na utilidades', 'A eficiência na drenagem aumenta a vida útil dos elementos filtrantes, mantendo os parâmetros de umidade em condições aceitáveis.  ', '1a1f0aa9_60e5_4151_90a6_1481e75a5801.jpg', '4ff111a8_b84b_4732_88e3_8126bbdc3fe8.jpg', 1157, 1071, 1158, 0, 0, 0, '2025-01-20', '2025-01-22', 2, 1179, 2, 2, 4, 1, 'locais que necessita acesso a tanques para realização de limpeza constante', 0, ''),
(1426, 0, 2, 0, 0, 0, 0, 'Padronização nas etiquetas de identificação das engraxadeiras usadas na lubrificação', 'Qualidade na visualização e identificação das engraxadeiras,e menos risco de erro na escolha de em emergência, alguém pegar uma engraxadeira errada', 'img_20250121_143838819_mfnr.jpg', 'img_20250121_144016747_mfnr.jpg', 1097, 1153, 0, 0, 0, 0, '2025-01-21', '2025-01-22', 2, 1179, 2, 2, 4, 1, 'Todos utensílios que precisam de identificação', 0, ''),
(1427, 0, 2, 0, 0, 0, 0, 'Padronização nas etiquetas de identificação das engraxadeiras usadas na lubrificação', 'Qualidade na visualização e identificação das engraxadeiras,e menos risco de erro na escolha de em emergência, alguém pegar uma engraxadeira errada', 'img_20250121_143838819_mfnr_250121040057.jpg', 'img_20250121_144016747_mfnr_250121040059.jpg', 1097, 1153, 0, 0, 0, 0, '2025-01-21', '2025-01-22', 3, 1179, 0, 2, 4, 1, 'Todos utensílios que precisam de identificação', 0, ''),
(1428, 0, 4, 0, 0, 0, 0, 'As ARTs (Análise de Risco de Tarefas) que temos atualmente na planta foram transferidas do Sharepoint para o IDOC.', 'Com essa mudança conseguimos manter de forma robusta os arquivos dentro do ciclo de revisão, comprovando aprovação do gestor e dpto de EHS, garantir a reavaliação dessas análises e comprovar o treinamento dos times envolvidos. ', '', '', 1092, 0, 0, 0, 0, 0, '2025-01-22', '2025-01-27', 2, 1082, 2, 2, 3, 2, '', 0, ''),
(1429, 0, 3, 0, 0, 0, 0, 'Bomba 5657\r\nTroca do lubrificação Castrol Spheerol EPL 2 que tem seu ponto de ignição em 150° para o lubrificação Rocol HI-TEMP 2 onde o ponto de ignição da mesma é 220°', 'Por se tratar de uma área quente no momento, precaução ', 'img_20250122_141405339_mfnr.jpg', 'img_20250122_141405339_mfnr_250122023437.jpg', 1097, 1160, 1155, 0, 0, 0, '2025-01-22', '2025-01-24', 2, 1179, 2, 2, 4, 1, 'Equipamentos que estejam necessitando de um lubrificante com maior aderência a temperatura elevada', 0, ''),
(1430, 0, 2, 0, 0, 0, 0, 'Bomba 5657\r\nInstalação de prolongador para lubrificação ', 'Melhoria na execução de lubrificação,e menos risco de derramamento de lubrificante para área sem acesso de limpeza ', 'img_20250122_141421663_mfnr.jpg', 'img_20250122_141405339_mfnr_250122024054.jpg', 1097, 1067, 1155, 0, 0, 0, '2025-01-22', '2025-01-24', 2, 1179, 2, 2, 4, 1, 'Pontos de lubrificação com difícil acesso', 0, ''),
(1431, 0, 2, 0, 0, 0, 0, 'Padronização e identificação dos galões OIL SAFE ', 'Qualidade na visualização e identificação dos galões OIL SAFE ,e menos risco de erro na escolha de em emergência, alguém pegar um galão errado\r\n\r\n', 'img_20250124_152422698_mfnr.jpg', 'img_20250124_152530901_hdr.jpg', 1097, 1153, 1066, 0, 0, 0, '2025-01-24', '2025-01-28', 2, 1179, 2, 2, 4, 1, 'Recipientes de produtos que necessitam etiquetas', 0, ''),
(1432, 0, 1, 15, 2412, 0, 0, 'Identificado como o sistema SAP busca os valores que vão no certificado de análise, identificando que não há a necessidade de cálculo das médias a cada corrida de produção, feita pelo laboratório.', 'Com a ideia há saving de tempo e financeiro (hora homem), além de maior precisão dos resultados uma vez que o valor antes inserido estava retroalimentando o cálculo automático do SAP.', 'saving.jpg', '', 1092, 1094, 0, 0, 0, 0, '2025-01-27', '2025-01-27', 2, 1082, 2, 2, 3, 2, '', 0, ''),
(1433, 0, 2, 0, 0, 0, 0, 'Realizado a troca da válvula on/off do backup da caldeira de recuperação que estava travada por está muito tempo sem uso.\r\nTAG: HSO.1131.16', 'válvula se encontra fechada para a caldeira e num evento o operador manda o comando para abrir suprindo as necessidades do nível', '13439296_2d4b_44ba_89ea_783c12c63372.jpg', '8e804fa1_a944_48e3_8398_9ce498ed4eaf.jpg', 1157, 1071, 1154, 0, 0, 0, '2025-01-31', '2025-01-31', 2, 1179, 2, 2, 4, 1, 'dreno de tanques e outros', 0, ''),
(1434, 0, 4, 0, 0, 0, 0, 'Foi ajustado o alarme  do P5358.02 de ar seco de ar comprimido de 6 bar para 6,3 bar , pelo fato de ocorrer a queda brusca de pressão quando o sistema faz  a regeneração do outro secador, acarretando no risco de  queda das plantas por pressão baixa, com esse alarme eleva-se o tempo hábil de atuação do operador caso necessário. \r\n', 'Uma atenção maior para queda brusca da pressão do ar comprimido seco, evitando a queda das plantas.', '', '', 1086, 1163, 1077, 0, 0, 0, '2025-02-05', '2025-02-24', 2, 1039, 2, 2, 1, 2, '', 0, ''),
(1435, 0, 2, 24, 0, 0, 0, 'Foi eliminada a necessidade de criar uma aprovação de preço nos sistema para cada solicitação de amostra.\r\nA partir de agora, vendas vai informar o preço na própria solicitação de amostra e CS vai inserir este preço manualmente na ordem de amostra no SAP.\r\nObs: Vendas vai continuar informando o preço a ser considerado na amostra, mas isso será feito diretamente na solicitação de amostra no campo designado para isso.', '1) Eliminou o trabalho de vendas que precisava criar a solicitação de aprovação de preço.\r\n2) Eliminou o trabalho de pricing que precisava aprovar o preço no sistema.\r\n3) Eliminou trabalho de marketing ou diretoria que precisava também aprovar o preço.\r\n4) Mais agilidade no envio das amostras, pois não há a necessidade de ficar aguardando o preço ser cadastrado.\r\n5) Sistema SFDC e SAP mais limpos, sem vários preços cadastrados sem necessidade.', 'price_approval.jpg', 'sample_request.jpg', 1050, 1094, 0, 0, 0, 0, '2025-02-06', '2025-02-06', 2, 1038, 2, 3, 9, 2, '', 0, ''),
(1436, 0, 4, 0, 0, 0, 0, 'Foi providenciado uma caixa adequada para deixar as chaves do caminhão enquanto descarrega.', 'Mais organizado e adequado.', '', '', 1076, 1081, 1086, 0, 0, 0, '2025-02-10', '2025-02-18', 2, 1039, 2, 2, 1, 0, '', 0, ''),
(1437, 0, 4, 0, 0, 0, 0, 'Foi ajustado  o nível do 5210 para 93% para manter a água para caldeira mais fria ,para melhorar  o nível da caldeira de recuperação que não está sendo suprida o suficiente pela bomba 5211 e 5212.', 'Melhora da manutenção do nível mínimo da caldeira de recuperação 1131.', '', '', 1086, 1076, 1077, 0, 0, 0, '2025-02-10', '2025-02-24', 2, 1039, 2, 2, 1, 2, '', 0, ''),
(1438, 0, 2, 0, 0, 0, 0, 'Confecção de tampas para câmaras dos absortômetros.', 'Auxiliar na prevenção contra umidade nas câmaras dos absortômetro.', '', '', 1093, 1092, 0, 0, 0, 0, '2025-02-12', '2025-02-24', 2, 1082, 2, 2, 3, 2, '', 0, ''),
(1439, 0, 2, 0, 0, 0, 0, 'Construído e instalado suporte coletor de copos plásticos descartáveis da oficina.', 'Melhora na limpeza e organização próximo ao bebedouro de e café da oficina. ', 'lixeira.jpg', 'suporte_p_copos.jpg', 1067, 1151, 1152, 0, 0, 0, '2025-02-12', '2025-02-12', 2, 1179, 2, 2, 4, 1, 'Nos demais setores', 0, ''),
(1440, 0, 2, 0, 0, 0, 0, 'Enviado selo mecânico da bomba 5212 para conserto, que quando danifica costuma-se  substituir por novo, mas como tínhamos usado todos os do estoque na bomba 5211 ficou em zero e a compra demora pois ele é importado. ', 'O selo recuperado funcionou bem e resolveu o problema do vazamento da bomba 5212, está operando normalmente', 'selo_danificado.jpg', 'selo_recuperado.jpg', 1067, 1070, 1173, 0, 0, 0, '2025-02-12', '2025-02-12', 2, 1179, 2, 2, 4, 0, '', 0, '');
INSERT INTO `kaizen` (`id_kaizen`, `categoria_kaizen`, `tipo_kaizen`, `tempo_kaizen`, `custo_kaizen`, `reducao_kaizen`, `destaque_kaizen`, `onde_kaizen`, `resultado_kaizen`, `imagem1_kaizen`, `imagem2_kaizen`, `colaborador_kaizen`, `colaborador1_kaizen`, `colaborador2_kaizen`, `colaborador3_kaizen`, `colaborador4_kaizen`, `lider_kaizen`, `datacadastro_kaizen`, `dataconclusao_kaizen`, `status_kaizen`, `admin_kaizen`, `pontos_kaizen`, `unidade_kaizen`, `setor_kaizen`, `outrosdep_kaizen`, `qual_kaizen`, `incidente_kaizen`, `obs_kaizen`) VALUES
(1441, 0, 2, 0, 0, 0, 0, 'Instalado suporte de papel tolha na parede próximo ao bebedouro da oficina e abaixado o suporte de papel toalha do banheiro pois ficava muito alta para pessoal da limpeza fazer a reposição dos papeis. ', 'Melhora na organização e para repor os papeis no suporte.', 'e0dfad41_cee5_4b1b_8f7e_5463dc5fd688.jpg', '042ed515_9312_4fca_8db0_5a943abcb269.jpg', 1067, 1173, 1070, 0, 0, 0, '2025-02-12', '2025-02-12', 2, 1179, 2, 2, 4, 0, '', 0, ''),
